import { useEffect, useState } from 'react';
import { ensureLeafletCore } from './loadLeafletCdn';

/** HMR / StrictMode: div còn `_leaflet_id` → `L.map` ném "Map container is already initialized". */
export function resetLeafletContainer(el: HTMLElement | null | undefined): void {
  if (!el) return;
  const marked = el as HTMLElement & { _leaflet_id?: number };
  if (!marked._leaflet_id) return;
  delete marked._leaflet_id;
  el.replaceChildren();
  el.className = el.className
    .split(/\s+/)
    .filter((c) => c && !c.startsWith('leaflet'))
    .join(' ');
}

/** Leaflet core only (no Draw) — Kind F monitor map. */
export function useLeaflet(): { ready: boolean; error: string | null } {
  const [ready, setReady] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      try {
        await ensureLeafletCore();
        if (!cancelled) setReady(true);
      } catch (e) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : 'Failed to load Leaflet');
        }
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  return { ready, error };
}
