/**
 * Index nét tuyến đã OSRM — show/hide theo Lớp, không route lại cả nước.
 * Memory + IndexedDB. z≤8 chỉ paint từ index (cấm live OSRM).
 */

const DB_NAME = 'rmms-osrm-line-index';
const DB_VER = 1;
const STORE = 'lines';

export type OsrmIndexedLine = {
  id: string;
  geomKey: string;
  path: [number, number][];
  routeKey: string;
  refWays: [number, number][][];
};

const mem = new Map<string, OsrmIndexedLine>();
let boot: Promise<void> | null = null;

function recKey(id: string, geomKey: string): string {
  return `${id}|${geomKey}`;
}

/** Fingerprint km-chain dump — đổi tọa độ → miss → OSRM lại. */
export function lineGeomKey(path: [number, number][]): string {
  if (path.length < 2) return '';
  const a = path[0];
  const b = path[path.length - 1];
  const mid = path[Math.floor(path.length / 2)];
  return [
    path.length,
    a[0].toFixed(5),
    a[1].toFixed(5),
    mid[0].toFixed(5),
    mid[1].toFixed(5),
    b[0].toFixed(5),
    b[1].toFixed(5),
  ].join(':');
}

function openDb(): Promise<IDBDatabase | null> {
  if (typeof indexedDB === 'undefined') return Promise.resolve(null);
  return new Promise((resolve) => {
    try {
      const req = indexedDB.open(DB_NAME, DB_VER);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE)) {
          const store = db.createObjectStore(STORE, { keyPath: 'id' });
          store.createIndex('geomKey', 'geomKey', { unique: false });
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
}

function loadAllFromDb(db: IDBDatabase): Promise<OsrmIndexedLine[]> {
  return new Promise((resolve) => {
    try {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).getAll();
      req.onsuccess = () => resolve((req.result as OsrmIndexedLine[]) || []);
      req.onerror = () => resolve([]);
    } catch {
      resolve([]);
    }
  });
}

export function ensureOsrmLineIndex(): Promise<void> {
  if (boot) return boot;
  boot = (async () => {
    const db = await openDb();
    if (!db) return;
    const rows = await loadAllFromDb(db);
    db.close();
    for (const rec of rows) {
      if (!rec?.id || !rec.geomKey || !Array.isArray(rec.path) || rec.path.length < 2) continue;
      mem.set(recKey(rec.id, rec.geomKey), rec);
    }
  })();
  return boot;
}

export function lookupOsrmIndexedLine(id: string, geomKey: string): OsrmIndexedLine | undefined {
  if (!id) return undefined;
  if (geomKey) {
    const hit = mem.get(recKey(id, geomKey));
    if (hit) return hit;
  }
  for (const rec of mem.values()) {
    if (rec.id === id && rec.path.length >= 2) return rec;
  }
  return undefined;
}

function putDb(rec: OsrmIndexedLine): void {
  void (async () => {
    const db = await openDb();
    if (!db) return;
    try {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(rec);
      tx.oncomplete = () => db.close();
      tx.onerror = () => db.close();
    } catch {
      try {
        db.close();
      } catch {
        /* ignore */
      }
    }
  })();
}

export function rememberOsrmIndexedLine(rec: OsrmIndexedLine): void {
  if (!rec.id || !rec.geomKey || rec.path.length < 2) return;
  mem.set(recKey(rec.id, rec.geomKey), rec);
  putDb(rec);
}

function foldRouteKey(raw: string): string {
  return String(raw || '')
    .trim()
    .toUpperCase()
    .replace(/[Đđ]/g, 'D')
    .replace(/[^A-Z0-9]/g, '');
}

/** Hành lang đã bake/index theo mã tuyến — cùng `{LiveGis}` `byRoute`. */
export function lookupOsrmPathsByRouteKey(routeKey: string): [number, number][][] {
  const want = foldRouteKey(routeKey);
  if (!want) return [];
  const out: [number, number][][] = [];
  for (const rec of mem.values()) {
    if (rec.path.length < 2) continue;
    const got = foldRouteKey(rec.routeKey);
    if (got && (got === want || got.startsWith(want) || want.startsWith(got))) {
      out.push(rec.path);
    }
  }
  return out;
}
