/**
 * OSRM route + nearest — port Demo `_shared/osrm-route` + `snap-to-street`.
 * GAP-MAP-OSRM-ROUTE · GAP-MAP-OSRM-SNAP
 *
 * Inventory km-chain: `/route` seed thưa (routeKmChainAlongHighway).
 * OSM `ref` chỉ khi `VITE_OVERPASS_URL` (self-host). Cấm Overpass public từ browser.
 * Draw CREATED / non-QL: `/route`; `/match` 100m không dùng cho chuỗi km lưới.
 */

const OSRM_PUBLIC = (import.meta.env.VITE_OSRM_URL || '').replace(/\/$/, '') || 'https://router.project-osrm.org';
const OSRM_ROUTE = `${OSRM_PUBLIC}/route/v1/driving`;
const OSRM_MATCH = `${OSRM_PUBLIC}/match/v1/driving`;
const OSRM_NEAREST = `${OSRM_PUBLIC}/nearest/v1/driving`;
const MAX_WAYPOINTS = 40;
/** Seed trước match — dày hơn 12 điểm/150 km (tránh OSRM nhảy QL song song). */
export const OSRM_MATCH_THIN = 40;
export const OSRM_MATCH_RADIUS_M = 100;
const MIN_MATCH_CONFIDENCE = 0.2;
/** Jump lớn hơn khoảng cách sample km-chain QL.1 (~87 km) — cắt chord xuyên tỉnh. */
export const OSRM_JUMP_SPLIT_KM = 150;
/** Cạnh stitch / khép vòng (7→1) — OSRM `overview=full` không nhảy vài km một đỉnh. */
export const OSRM_DRAW_JUMP_KM = 3;
/** Km-chain inventory: /route giữa seed thưa — /match 100m bám đường làng cạnh lưới 2 số thập phân. */
export const OSRM_CHAIN_THIN = 12;
/** Via trên QL sau khi ghim — quá dày thì OSRM đi từng khối phố (bậc thang). */
const OSRM_HIGHWAY_VIA = 6;
/** ~150 m — không nhét 2 pin cùng ngã tư. */
const MIN_PIN_SPACING_DEG2 = 0.0014 ** 2;
const HIGHWAY_SNAP_RADIUS_M = 40;
const GRID_RIGHT_ANGLE_RATIO = 0.38;

const EARTH_KM = 6371;

function haversineKm(a: [number, number], b: [number, number]): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(b[0] - a[0]);
  const dLng = toRad(b[1] - a[1]);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a[0])) * Math.cos(toRad(b[0])) * Math.sin(dLng / 2) ** 2;
  return 2 * EARTH_KM * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Tách LineString khi hai điểm liên tiếp nhảy > maxJumpKm (km-chain lẫn tuyến). */
export function splitPathOnJump(
  latLngs: [number, number][],
  maxJumpKm = OSRM_JUMP_SPLIT_KM,
): [number, number][][] {
  if (latLngs.length < 2) return [];
  const segs: [number, number][][] = [];
  let cur: [number, number][] = [latLngs[0]];
  for (let i = 1; i < latLngs.length; i += 1) {
    const next = latLngs[i];
    const prev = cur[cur.length - 1];
    if (haversineKm(prev, next) > maxJumpKm) {
      if (cur.length >= 2) segs.push(cur);
      cur = [next];
    } else {
      cur.push(next);
    }
  }
  if (cur.length >= 2) segs.push(cur);
  return segs;
}

/** Bỏ ring đóng + cạnh nhảy (chord 7→1). Giữ đoạn dày dài nhất. */
export function longestOpenPath(
  path: [number, number][],
  maxJumpKm = OSRM_DRAW_JUMP_KM,
): [number, number][] {
  if (!path || path.length < 2) return [];
  const opened = path.slice();
  if (opened.length >= 3 && haversineKm(opened[0], opened[opened.length - 1]) < 0.08) {
    opened.pop();
  }
  const segs = splitPathOnJump(opened, maxJumpKm);
  if (!segs.length) return [];
  segs.sort((a, b) => pathLengthKm(b) - pathLengthKm(a) || b.length - a.length);
  return segs[0];
}

export function decodePolyline(str: string, precision = 5): [number, number][] {
  let index = 0;
  const len = str.length;
  let lat = 0;
  let lng = 0;
  const coordinates: [number, number][] = [];
  const factor = 10 ** (precision ?? 5);

  while (index < len) {
    let result = 0;
    let shift = 0;
    let b: number;
    do {
      b = str.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    const dlat = result & 1 ? ~(result >> 1) : result >> 1;
    lat += dlat;

    result = 0;
    shift = 0;
    do {
      b = str.charCodeAt(index++) - 63;
      result |= (b & 0x1f) << shift;
      shift += 5;
    } while (b >= 0x20);
    const dlng = result & 1 ? ~(result >> 1) : result >> 1;
    lng += dlng;

    coordinates.push([lat / factor, lng / factor]);
  }
  return coordinates;
}

function toLngLatPairs(latLngs: [number, number][]): string[] {
  return latLngs
    .map(([lat, lng]) => {
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
      return `${lng},${lat}`;
    })
    .filter(Boolean) as string[];
}

async function fetchOsrmJson(url: string): Promise<{ status: number; data: Record<string, unknown> }> {
  const res = await fetch(url);
  const data = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  return { status: res.status, data };
}

function pathLengthKm(pts: [number, number][]): number {
  let n = 0;
  for (let i = 1; i < pts.length; i += 1) n += haversineKm(pts[i - 1], pts[i]);
  return n;
}

/** GPS thưa / chord cắt map — OSRM tim đường luôn dày vertex. */
export function isSparseGpsChord(path: [number, number][]): boolean {
  if (path.length < 2) return true;
  const km = pathLengthKm(path);
  if (km < 0.15) return false;
  return path.length / km < 8;
}

/** Tỉ lệ rẽ ~90° — lưới phố / đường tránh cầu, không phải tim QL. */
export function gridTurnRatio(path: [number, number][]): number {
  if (path.length < 8) return 0;
  let turns = 0;
  let right = 0;
  for (let i = 1; i < path.length - 1; i += 1) {
    const a = path[i - 1];
    const b = path[i];
    const c = path[i + 1];
    const d1 = haversineKm(a, b);
    const d2 = haversineKm(b, c);
    if (d1 < 0.012 || d2 < 0.012) continue;
    const h1 = Math.atan2(b[1] - a[1], b[0] - a[0]);
    const h2 = Math.atan2(c[1] - b[1], c[0] - b[0]);
    let d = Math.abs(h2 - h1);
    if (d > Math.PI) d = 2 * Math.PI - d;
    if (d < 0.18) continue;
    turns += 1;
    if (Math.abs(d - Math.PI / 2) < 0.32) right += 1;
  }
  return turns < 5 ? 0 : right / turns;
}

function isGridWalk(path: [number, number][]): boolean {
  return gridTurnRatio(path) >= GRID_RIGHT_ANGLE_RATIO;
}

function highwayRouteScore(path: [number, number][], seedKm: number): number {
  const grid = gridTurnRatio(path);
  const len = pathLengthKm(path);
  const detour = seedKm > 0.3 ? len / seedKm : 1;
  return grid * 6 + Math.max(0, detour - 1.12) * 2;
}

async function fetchOsrmHighwaySegment(latLngs: [number, number][]): Promise<[number, number][]> {
  const coords = toLngLatPairs(latLngs);
  if (coords.length < 2) return latLngs;
  const radiuses = coords.map(() => String(HIGHWAY_SNAP_RADIUS_M)).join(';');
  const url =
    `${OSRM_ROUTE}/${coords.join(';')}?overview=full&geometries=polyline` +
    `&continue_straight=true&alternatives=true&radiuses=${radiuses}`;
  const { status, data } = await fetchOsrmJson(url);
  if (status < 200 || status >= 300) throw new Error(`OSRM route HTTP ${status}`);
  const routes = data.routes as Array<{ geometry?: string }> | undefined;
  if (data.code !== 'Ok' || !routes?.length) {
    throw new Error('OSRM không trả được tuyến đường');
  }
  const paths = routes
    .map((r) => (r.geometry ? decodePolyline(r.geometry) : []))
    .filter((p) => p.length >= 2);
  if (!paths.length) throw new Error('OSRM không trả được tuyến đường');
  const seedKm = pathLengthKm(latLngs);
  paths.sort((a, b) => highwayRouteScore(a, seedKm) - highwayRouteScore(b, seedKm));
  const best = paths[0];
  if (isGridWalk(best)) throw new Error('OSRM đi lưới phố / nhánh cầu');
  if (seedKm > 1 && pathLengthKm(best) > seedKm * 2.2) {
    throw new Error('OSRM detour khỏi quốc lộ');
  }
  return best;
}

async function fetchOsrmRouteSegment(latLngs: [number, number][]): Promise<[number, number][]> {
  const coords = toLngLatPairs(latLngs);
  if (coords.length < 2) return latLngs;
  const url = `${OSRM_ROUTE}/${coords.join(';')}?overview=full&geometries=polyline&continue_straight=true`;
  const { status, data } = await fetchOsrmJson(url);
  if (status < 200 || status >= 300) throw new Error(`OSRM route HTTP ${status}`);
  const routes = data.routes as Array<{ geometry?: string }> | undefined;
  if (data.code !== 'Ok' || !routes?.[0]?.geometry) {
    throw new Error('OSRM không trả được tuyến đường');
  }
  return decodePolyline(routes[0].geometry);
}

async function fetchOsrmMatchSegment(latLngs: [number, number][]): Promise<[number, number][]> {
  const coords = toLngLatPairs(latLngs);
  if (coords.length < 2) return latLngs;
  const radiuses = coords.map(() => String(OSRM_MATCH_RADIUS_M)).join(';');
  const url = `${OSRM_MATCH}/${coords.join(';')}?overview=full&geometries=polyline&radiuses=${radiuses}&gaps=split&tidy=true`;
  const { status, data } = await fetchOsrmJson(url);
  if (status < 200 || status >= 300) {
    throw new Error(`OSRM match HTTP ${status}`);
  }
  if (data.code !== 'Ok') {
    throw new Error(String(data.code || 'OSRM match thất bại'));
  }
  const matchings = data.matchings as Array<{ geometry?: string; confidence?: number }> | undefined;
  if (!matchings?.length) throw new Error('OSRM match trống');
  const bestConf = Math.max(...matchings.map((m) => Number(m.confidence) || 0));
  if (bestConf > 0 && bestConf < MIN_MATCH_CONFIDENCE) {
    throw new Error('OSRM match confidence thấp');
  }
  const parts: [number, number][] = [];
  for (const m of matchings) {
    if (!m.geometry) continue;
    const geom = decodePolyline(m.geometry);
    if (!parts.length) parts.push(...geom);
    else parts.push(...geom.slice(1));
  }
  if (parts.length < 2) throw new Error('OSRM match geometry ngắn');
  return parts;
}

function chunkWaypoints(latLngs: [number, number][], size: number): [number, number][][] {
  if (latLngs.length <= size) return [latLngs];
  const chunks: [number, number][][] = [];
  let i = 0;
  while (i < latLngs.length - 1) {
    const end = Math.min(i + size, latLngs.length);
    chunks.push(latLngs.slice(i, end));
    if (end >= latLngs.length) break;
    i = end - 1;
  }
  return chunks;
}

const routeCache = new Map<string, [number, number][]>();

function cacheKey(prefix: string, latLngs: [number, number][]): string {
  return `${prefix}:${latLngs.map((p) => `${(+p[0]).toFixed(5)},${(+p[1]).toFixed(5)}`).join(';')}`;
}

/** Giảm waypoint theo quãng đường — giữ đầu/cuối, sample đều km. */
export function thinWaypoints(latLngs: [number, number][], max = OSRM_MATCH_THIN): [number, number][] {
  if (latLngs.length <= max) return latLngs;
  if (max < 2) return [latLngs[0], latLngs[latLngs.length - 1]];
  const dist = [0];
  for (let i = 1; i < latLngs.length; i += 1) {
    dist.push(dist[i - 1] + haversineKm(latLngs[i - 1], latLngs[i]));
  }
  const total = dist[dist.length - 1];
  if (total < 1e-6) return [latLngs[0], latLngs[latLngs.length - 1]];
  const out: [number, number][] = [latLngs[0]];
  let nextIdx = 1;
  const step = total / (max - 1);
  for (let i = 1; i < latLngs.length - 1; i += 1) {
    if (dist[i] + 1e-9 < nextIdx * step) continue;
    out.push(latLngs[i]);
    nextIdx += 1;
    if (out.length >= max - 1) break;
  }
  out.push(latLngs[latLngs.length - 1]);
  return out;
}

async function routeChunks(
  waypoints: [number, number][],
  fetchSeg: (pts: [number, number][]) => Promise<[number, number][]>,
): Promise<[number, number][]> {
  const chunks = chunkWaypoints(waypoints, MAX_WAYPOINTS);
  const parts: [number, number][] = [];
  for (let c = 0; c < chunks.length; c += 1) {
    const geom = await fetchSeg(chunks[c]);
    if (c === 0) parts.push(...geom);
    else parts.push(...geom.slice(1));
  }
  return parts;
}

export type PathProjection = {
  seg: number;
  t: number;
  point: [number, number];
};

/** Ghim điểm lên polyline đã OSRM — trả segment + t (cùng phép với nét vẽ). */
export function projectToPathHit(
  lat: number,
  lng: number,
  path: [number, number][],
): PathProjection {
  if (!path.length) return { seg: 0, t: 0, point: [lat, lng] };
  if (path.length === 1) return { seg: 0, t: 0, point: path[0] };
  let best: PathProjection = { seg: 0, t: 0, point: path[0] };
  let bestD = Infinity;
  for (let i = 1; i < path.length; i += 1) {
    const a = path[i - 1];
    const b = path[i];
    const dx = b[1] - a[1];
    const dy = b[0] - a[0];
    const len2 = dx * dx + dy * dy;
    const t = len2 < 1e-18 ? 0 : Math.max(0, Math.min(1, ((lng - a[1]) * dx + (lat - a[0]) * dy) / len2));
    const pLat = a[0] + t * dy;
    const pLng = a[1] + t * dx;
    const d = (pLat - lat) ** 2 + (pLng - lng) ** 2;
    if (d < bestD) {
      bestD = d;
      best = { seg: i - 1, t, point: [pLat, pLng] };
    }
  }
  return best;
}

/** Ghim điểm lên polyline đã OSRM (không gọi nearest 90 lần). */
export function projectToPath(lat: number, lng: number, path: [number, number][]): [number, number] {
  return projectToPathHit(lat, lng, path).point;
}

/**
 * Ghim lên hành lang gần nhất. Bỏ qua path lệch quá maxDistDeg (cấm kéo pin Tam Kỳ lên tuyến Hà Nội).
 */
export function projectToNearestPath(
  lat: number,
  lng: number,
  paths: Iterable<[number, number][]>,
  maxDistDeg = 0.04,
): [number, number] {
  const maxD = maxDistDeg * maxDistDeg;
  let best: [number, number] = [lat, lng];
  let bestD = maxD;
  let hit = false;
  for (const path of paths) {
    if (!path || path.length < 2) continue;
    const p = projectToPath(lat, lng, path);
    const d = (p[0] - lat) ** 2 + (p[1] - lng) ** 2;
    if (d <= bestD) {
      bestD = d;
      best = p;
      hit = true;
    }
  }
  return hit ? best : [lat, lng];
}

/** Polyline bám tim đường — match OSM way; fail → route. */
export async function routeAlongStreets(
  points: Array<[number, number] | { lat: number; lng: number }>,
): Promise<[number, number][]> {
  const latLngs = (points || [])
    .map((p) => {
      if (Array.isArray(p)) return [Number(p[0]), Number(p[1])] as [number, number];
      return [Number(p.lat), Number(p.lng)] as [number, number];
    })
    .filter((p) => Number.isFinite(p[0]) && Number.isFinite(p[1]));

  if (latLngs.length < 2) return latLngs;
  const jumpSegs = splitPathOnJump(latLngs);
  if (jumpSegs.length === 0) {
    throw new Error('OSRM skip jump-only chain');
  }
  if (jumpSegs.length > 1) {
    const routedSegs: [number, number][][] = [];
    for (const seg of jumpSegs) {
      routedSegs.push(await routeAlongStreets(seg));
    }
    routedSegs.sort((a, b) => b.length - a.length);
    return routedSegs[0] || latLngs;
  }
  const waypoints = thinWaypoints(jumpSegs[0], OSRM_MATCH_THIN);
  const key = cacheKey(`m${OSRM_MATCH_THIN}r${OSRM_MATCH_RADIUS_M}`, waypoints);
  if (routeCache.has(key)) return routeCache.get(key)!;

  try {
    const matched = await routeChunks(waypoints, fetchOsrmMatchSegment);
    routeCache.set(key, matched);
    return matched;
  } catch {
    const routed = await routeChunks(waypoints, fetchOsrmRouteSegment);
    routeCache.set(key, routed);
    return routed;
  }
}

/**
 * Self-host Overpass only (`VITE_OVERPASS_URL`). Empty = skip.
 * Cấm overpass-api.de / kumi.systems từ browser — 429 + CORS 500.
 */
function overpassEndpoints(): string[] {
  const raw = String(import.meta.env.VITE_OVERPASS_URL || '').trim();
  if (!raw) return [];
  return raw
    .split(',')
    .map((s) => s.trim().replace(/\/$/, ''))
    .filter(Boolean);
}
const osmWayCache = new Map<string, [number, number][][]>();

function normalizeRouteKey(raw: string): string {
  return String(raw || '')
    .trim()
    .toUpperCase()
    .replace(/[Đđ]/g, 'D')
    .replace(/[^A-Z0-9]/g, '');
}

function namedHighwayId(routeKey: string): 'QLTSDONG' | 'QLHCM' | '' {
  const k = normalizeRouteKey(routeKey);
  if (k === 'QLTSDONG' || k.includes('TRUONGSON')) return 'QLTSDONG';
  if (k === 'QLHCM' || k.includes('HOCHIMINH')) return 'QLHCM';
  return '';
}

function isNationalHighwayKey(routeKey: string): boolean {
  const k = normalizeRouteKey(routeKey);
  return /^QL\d/.test(k) || Boolean(namedHighwayId(routeKey));
}

/** Overpass POSIX: QL.1 / QL.1;AH1 — cấm khớp QL.14. Named QL: không dùng ref số. */
export function osmHighwayRefRegex(routeKey: string): string {
  if (namedHighwayId(routeKey)) return '';
  const k = normalizeRouteKey(routeKey);
  const m = /^QL(\d+)([A-Z]?)$/.exec(k);
  if (!m) return '';
  const n = m[1];
  const suf = m[2] || '';
  if (suf) return `QL[.]?${n}${suf}`;
  return `QL[.]?${n}([^0-9]|$)`;
}

/** Overpass `name` cho tuyến named (Trường Sơn Đông · Hồ Chí Minh). */
export function osmHighwayNameRegex(routeKey: string): string {
  const id = namedHighwayId(routeKey);
  if (id === 'QLTSDONG') return 'Trường Sơn Đông|Truong Son Dong';
  if (id === 'QLHCM') return 'Hồ Chí Minh|Ho Chi Minh';
  return '';
}

function foldOsmName(raw: string): string {
  return String(raw || '')
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .replace(/[Đđ]/g, 'D')
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, ' ')
    .trim();
}

/** OSM `name` «Quốc lộ 20» / «QL.20» / «Đường Trường Sơn Đông». Fold NFD. */
export function osmNameMatchesRoute(name: string, routeKey: string): boolean {
  const folded = foldOsmName(name);
  if (folded.length < 3) return false;
  if (isSpurRoadName(folded, routeKey)) return false;
  const named = namedHighwayId(routeKey);
  if (named === 'QLTSDONG') {
    if (/TRUONG\s*SON\s*TAY/.test(folded)) return false;
    return /TRUONG\s*SON(\s*DONG)?/.test(folded);
  }
  if (named === 'QLHCM') return /HO\s*CHI\s*MINH/.test(folded);
  const k = normalizeRouteKey(routeKey);
  const m = /^QL(\d+)([A-Z]?)$/.exec(k);
  if (!m) return false;
  const n = m[1];
  const suf = m[2] || '';
  const padded = ` ${folded} `;
  const sufPat = suf ? `\\s*${suf}` : '';
  const ql = new RegExp(`(?:^| )QL\\s*${n}${sufPat}(?: |$)`);
  const quoc = new RegExp(`(?:^| )QUOC\\s*LO\\s*${n}${sufPat}(?: |$)`);
  if (ql.test(padded) || quoc.test(padded)) return true;
  return n === '1' && !suf && /(?:^| )AH\s*1(?: |$)/.test(padded);
}

/** Đường tránh cầu / nhánh / hẻm / ĐT — đi qua cầu trên trục, không vào nhánh. */
function isSpurRoadName(folded: string, routeKey: string): boolean {
  const f = folded;
  const rk = normalizeRouteKey(routeKey);
  if (/TRANH\s*CAU|DUONG\s*TRANH/.test(f)) return true;
  if (/\bNHANH\b/.test(f)) return true;
  if (/\bHEM\b|\bNGO\b|\bKIET\b/.test(f)) return true;
  if (/DUONG\s*VAO|DUONG\s*LANG|NGO\s*XOM/.test(f)) return true;
  if (!rk.startsWith('DT') && (/\bDT\s*\d/.test(f) || /DUONG\s*TINH/.test(f))) return true;
  return false;
}

function highwayNameRank(name: string, routeKey: string): number {
  const f = foldOsmName(name);
  if (!osmNameMatchesRoute(name, routeKey)) return -1;
  let s = 1;
  if (/QUOC\s*LO|QL\s*\d/.test(f)) s += 3;
  if (/TRUONG\s*SON\s*DONG/.test(f)) s += 3;
  else if (/TRUONG\s*SON/.test(f)) s += 1;
  return s;
}

function dist2(a: [number, number], b: [number, number]): number {
  const dLat = a[0] - b[0];
  const dLng = a[1] - b[1];
  return dLat * dLat + dLng * dLng;
}

function stitchWaysAlongSeeds(
  ways: [number, number][][],
  seeds: [number, number][],
): [number, number][] {
  if (!ways.length || seeds.length < 2) return [];
  const ordered = ways
    .map((w) => {
      const mid = w[Math.floor(w.length / 2)] || w[0];
      let bestI = 0;
      let best = Infinity;
      seeds.forEach((s, i) => {
        const d = dist2(s, mid);
        if (d < best) {
          best = d;
          bestI = i;
        }
      });
      return { w: w.slice(), bestI };
    })
    .sort((a, b) => a.bestI - b.bestI);
  const out: [number, number][] = [];
  const pieces: [number, number][][] = [];
  for (const { w: rawW } of ordered) {
    if (rawW.length < 2) continue;
    const w = rawW.slice();
    if (!out.length) {
      out.push(...w);
      continue;
    }
    const last = out[out.length - 1];
    if (dist2(last, w[w.length - 1]) < dist2(last, w[0])) w.reverse();
    if (haversineKm(last, w[0]) > OSRM_DRAW_JUMP_KM) {
      if (out.length >= 2) pieces.push(out.slice());
      out.length = 0;
      out.push(...w);
      continue;
    }
    out.push(...w.slice(1));
  }
  if (out.length >= 2) pieces.push(out);
  if (!pieces.length) return [];
  pieces.sort((a, b) => pathLengthKm(b) - pathLengthKm(a) || b.length - a.length);
  return pieces[0];
}

async function fetchOsmRefWays(
  routeKey: string,
  pts: [number, number][],
): Promise<[number, number][][]> {
  const endpoints = overpassEndpoints();
  const re = osmHighwayRefRegex(routeKey);
  const nameRe = osmHighwayNameRegex(routeKey);
  if (!endpoints.length || pts.length < 1) return [];
  if (!re && !nameRe) return [];
  const lats = pts.map((p) => p[0]);
  const lngs = pts.map((p) => p[1]);
  const pad = 0.02;
  const south = Math.min(...lats) - pad;
  const north = Math.max(...lats) + pad;
  const west = Math.min(...lngs) - pad;
  const east = Math.max(...lngs) + pad;
  const ck = `osm:${normalizeRouteKey(routeKey)}:${south.toFixed(3)}:${west.toFixed(3)}:${north.toFixed(3)}:${east.toFixed(3)}`;
  if (osmWayCache.has(ck)) return osmWayCache.get(ck)!;
  const filter = re
    ? `["ref"~"${re}"]`
    : `["name"~"${nameRe}",i]`;
  const query =
    `[out:json][timeout:20];way["highway"~"^(motorway|trunk|primary)$"]${filter}` +
    `(${south.toFixed(5)},${west.toFixed(5)},${north.toFixed(5)},${east.toFixed(5)});out geom;`;
  const body = `data=${encodeURIComponent(query)}`;
  for (const url of endpoints) {
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
        body,
      });
      if (!res.ok) continue;
      const data = (await res.json()) as {
        elements?: Array<{ geometry?: Array<{ lat: number; lon: number }> }>;
      };
      const ways: [number, number][][] = [];
      for (const el of data.elements || []) {
        const geom = (el.geometry || [])
          .map((n) => [Number(n.lat), Number(n.lon)] as [number, number])
          .filter((p) => Number.isFinite(p[0]) && Number.isFinite(p[1]));
        if (geom.length >= 2) ways.push(geom);
      }
      osmWayCache.set(ck, ways);
      return ways;
    } catch {
      /* next endpoint */
    }
  }
  osmWayCache.set(ck, []);
  return [];
}

async function snapPointToNamedHighway(
  lat: number,
  lng: number,
  routeKey: string,
): Promise<[number, number] | null> {
  if (!isNationalHighwayKey(routeKey)) return null;
  const url = `${OSRM_NEAREST}/${lng},${lat}?number=30`;
  const { status, data } = await fetchOsrmJson(url);
  if (status < 200 || status >= 300 || data.code !== 'Ok') return null;
  const wps = data.waypoints as Array<{ name?: string; distance?: number; location?: number[] }> | undefined;
  const hits = (wps || [])
    .map((w) => ({
      w,
      rank: highwayNameRank(String(w.name || ''), routeKey),
    }))
    .filter((x) => x.w.location && x.w.location.length >= 2 && x.rank > 0 && (x.w.distance || 0) <= 1500);
  if (!hits.length) return null;
  hits.sort((a, b) => b.rank - a.rank || (a.w.distance || 0) - (b.w.distance || 0));
  const loc = hits[0].w.location!;
  return [loc[1], loc[0]];
}

async function pinSeedsToHighway(
  seeds: [number, number][],
  routeKey: string,
  osmWays: [number, number][][],
): Promise<[number, number][]> {
  const pinned: [number, number][] = [];
  for (const [lat, lng] of seeds) {
    let hit: [number, number] | null = null;
    if (osmWays.length) {
      const p = projectToNearestPath(lat, lng, osmWays, 0.025);
      if (p[0] !== lat || p[1] !== lng) hit = p;
    }
    if (!hit && routeKey) hit = await snapPointToNamedHighway(lat, lng, routeKey);
    if (!hit) continue;
    const prev = pinned[pinned.length - 1];
    if (prev && dist2(prev, hit) < MIN_PIN_SPACING_DEG2) continue;
    pinned.push(hit);
  }
  return pinned;
}

export type HighwayRouteResult = {
  path: [number, number][];
  refWays: [number, number][][];
};

/**
 * Tuyến inventory (chuỗi cột km lưới Vidagis).
 * Ghim seed lên OSM `ref` = mã tuyến rồi `/route`. Cấm `/match` 100m / nearest=1 (đường làng song song QL).
 */
export async function routeKmChainAlongHighway(
  points: Array<[number, number] | { lat: number; lng: number }>,
  routeKey = '',
): Promise<HighwayRouteResult> {
  const latLngs = (points || [])
    .map((p) => {
      if (Array.isArray(p)) return [Number(p[0]), Number(p[1])] as [number, number];
      return [Number(p.lat), Number(p.lng)] as [number, number];
    })
    .filter((p) => Number.isFinite(p[0]) && Number.isFinite(p[1]));

  const empty: HighwayRouteResult = { path: latLngs, refWays: [] };
  if (latLngs.length < 2) return empty;
  const jumpSegs = splitPathOnJump(latLngs);
  if (jumpSegs.length === 0) {
    throw new Error('OSRM skip jump-only chain');
  }
  if (jumpSegs.length > 1) {
    const routedSegs: HighwayRouteResult[] = [];
    for (const seg of jumpSegs) {
      routedSegs.push(await routeKmChainAlongHighway(seg, routeKey));
    }
    routedSegs.sort((a, b) => b.path.length - a.path.length);
    const best = routedSegs[0];
    return {
      path: best?.path?.length ? best.path : latLngs,
      refWays: routedSegs.flatMap((r) => r.refWays),
    };
  }
  const waypoints = thinWaypoints(jumpSegs[0], OSRM_CHAIN_THIN);
  const osmWays = routeKey ? await fetchOsmRefWays(routeKey, waypoints) : [];
  const pinned = routeKey
    ? await pinSeedsToHighway(waypoints, routeKey, osmWays)
    : waypoints;
  if (pinned.length < 2) {
    if (isNationalHighwayKey(routeKey)) {
      throw new Error('OSRM không ghim được seed lên quốc lộ');
    }
  }
  const seeds = pinned.length >= 2 ? pinned : waypoints;
  const ck = cacheKey(`hwyG${OSRM_HIGHWAY_VIA}:${normalizeRouteKey(routeKey)}`, seeds);
  if (routeCache.has(ck)) {
    return { path: routeCache.get(ck)!, refWays: osmWays };
  }
  const stitched = stitchWaysAlongSeeds(osmWays, seeds);
  if (stitched.length >= 2 && !isGridWalk(stitched)) {
    routeCache.set(ck, stitched);
    return { path: stitched, refWays: osmWays };
  }
  const viaSets: [number, number][][] = [
    thinWaypoints(seeds, OSRM_HIGHWAY_VIA),
    thinWaypoints(seeds, 3),
    [seeds[0], seeds[seeds.length - 1]],
  ];
  let lastErr: Error | null = null;
  for (const via of viaSets) {
    if (via.length < 2) continue;
    try {
      const routed = await routeChunks(via, fetchOsrmHighwaySegment);
      if (routed.length < 2 || isGridWalk(routed)) {
        throw new Error('OSRM đi lưới phố / nhánh cầu');
      }
      const seedKm = pathLengthKm(via);
      const routeKm = pathLengthKm(routed);
      if (seedKm > 1 && routeKm > seedKm * 2.2) {
        throw new Error('OSRM detour khỏi quốc lộ');
      }
      routeCache.set(ck, routed);
      return { path: routed, refWays: osmWays };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
    }
  }
  throw lastErr || new Error('OSRM không bám quốc lộ');
}

function toLatLngs(
  points: Array<[number, number] | { lat: number; lng: number }>,
): [number, number][] {
  return (points || [])
    .map((p) => {
      if (Array.isArray(p)) return [Number(p[0]), Number(p[1])] as [number, number];
      return [Number(p.lat), Number(p.lng)] as [number, number];
    })
    .filter((p) => Number.isFinite(p[0]) && Number.isFinite(p[1]));
}

/**
 * Track tuần / overlay — cùng stack `{LiveGis}`:
 * 1) `routeKmChainAlongHighway` (OSM `ref` + `/route`)
 * 2) `/route` `continue_straight` (cấm `/match` 100m)
 * 3) throw → caller nét đứt (cấm im lặng chord)
 */
export async function routeDrivingTrack(
  points: Array<[number, number] | { lat: number; lng: number }>,
  routeKey = '',
): Promise<[number, number][]> {
  const latLngs = toLatLngs(points);
  if (latLngs.length < 2) return latLngs;
  try {
    const hwy = await routeKmChainAlongHighway(latLngs, routeKey);
    if (hwy.path.length >= 2) return hwy.path;
  } catch {
    /* driving */
  }
  const via = thinWaypoints(latLngs, Math.min(OSRM_HIGHWAY_VIA, latLngs.length));
  return routeChunks(via.length >= 2 ? via : latLngs, fetchOsrmRouteSegment);
}

/** Cắt hành lang giữa stop đầu–cuối (pin ghim đúng đoạn tuần). */
export function slicePathBetweenStops(
  path: [number, number][],
  stops: [number, number][],
): [number, number][] {
  if (path.length < 2) return path;
  if (stops.length < 2) return path;
  const idxs = stops.map((s) => {
    const p = projectToPath(s[0], s[1], path);
    let bestI = 0;
    let bestD = Infinity;
    for (let i = 0; i < path.length; i += 1) {
      const d = (path[i][0] - p[0]) ** 2 + (path[i][1] - p[1]) ** 2;
      if (d < bestD) {
        bestD = d;
        bestI = i;
      }
    }
    return bestI;
  });
  const a = Math.max(0, Math.min(...idxs));
  const b = Math.min(path.length - 1, Math.max(...idxs));
  const slice = path.slice(a, b + 1);
  return slice.length >= 2 ? slice : path;
}

function sameLatLng(a: [number, number], b: [number, number]): boolean {
  return Math.abs(a[0] - b[0]) < 1e-12 && Math.abs(a[1] - b[1]) < 1e-12;
}

function pushLatLng(out: [number, number][], p: [number, number]): void {
  if (!out.length || !sameLatLng(out[out.length - 1], p)) out.push(p);
}

function appendWalkHits(
  out: [number, number][],
  path: [number, number][],
  from: PathProjection,
  to: PathProjection,
): void {
  if (from.seg === to.seg) {
    pushLatLng(out, to.point);
    return;
  }
  if (from.seg < to.seg) {
    for (let i = from.seg + 1; i <= to.seg; i += 1) pushLatLng(out, path[i]);
    pushLatLng(out, to.point);
    return;
  }
  for (let i = from.seg; i > to.seg; i -= 1) pushLatLng(out, path[i]);
  pushLatLng(out, to.point);
}

function orientPathToStops(
  path: [number, number][],
  stops: [number, number][],
): [number, number][] {
  if (path.length < 2 || stops.length < 2) return path;
  const a = projectToPathHit(stops[0][0], stops[0][1], path);
  const b = projectToPathHit(stops[stops.length - 1][0], stops[stops.length - 1][1], path);
  if (a.seg > b.seg) return path.slice().reverse();
  return path;
}

/** Đi bộ polyline theo thứ tự pin 1→2→…→n — không khép vòng, không chord 7→1. */
export function walkPathThroughStops(
  path: [number, number][],
  stops: [number, number][],
): [number, number][] {
  const open = longestOpenPath(path);
  if (open.length < 2) return [];
  if (stops.length < 2) return open;
  const oriented = orientPathToStops(open, stops);
  const hits = stops.map((s) => projectToPathHit(s[0], s[1], oriented));
  const out: [number, number][] = [hits[0].point];
  for (let k = 0; k < hits.length - 1; k += 1) {
    const from = hits[k];
    const to = hits[k + 1];
    if (to.seg < from.seg || (to.seg === from.seg && to.t + 1e-9 < from.t)) {
      continue;
    }
    const at = out.length;
    appendWalkHits(out, oriented, from, to);
    const piece = out.slice(Math.max(0, at - 1));
    if (isSparseGpsChord(piece)) out.length = at;
  }
  return out.length >= 2 ? out : [];
}

/** Ghép đoạn 1–2, 2–3, … thành một polyline (không trùng đỉnh nối). */
export function concatPathSegments(segments: [number, number][][]): [number, number][] {
  const out: [number, number][] = [];
  for (const seg of segments) {
    if (seg.length < 2 || isSparseGpsChord(seg)) continue;
    const skipFirst = out.length > 0 && sameLatLng(out[out.length - 1], seg[0]);
    for (let i = skipFirst ? 1 : 0; i < seg.length; i += 1) pushLatLng(out, seg[i]);
  }
  return out;
}

/**
 * Nối từng cặp stop bằng `{OsrmRoute}` (đi cầu / đường, không chord).
 * Cấm `/match` 100m. Highway 40m fail → `/route` `continue_straight`.
 * Không `isGridWalk` cả chuỗi (QL trong phố luôn nhiều rẽ).
 */
export async function routeHighwayLegs(stops: [number, number][]): Promise<[number, number][]> {
  if (stops.length < 2) return stops;
  const segs: [number, number][][] = [];
  for (let i = 0; i < stops.length - 1; i += 1) {
    const pair: [number, number][] = [stops[i], stops[i + 1]];
    let routed: [number, number][] = [];
    try {
      routed = await fetchOsrmHighwaySegment(pair);
    } catch {
      routed = await fetchOsrmRouteSegment(pair);
    }
    if (routed.length < 2 || isSparseGpsChord(routed)) {
      throw new Error('OSRM không bám đường giữa hai điểm tuần');
    }
    segs.push(routed);
  }
  const out = concatPathSegments(segs);
  if (out.length < 2 || isSparseGpsChord(out)) {
    throw new Error('OSRM không bám tuyến giữa các điểm tuần');
  }
  return out;
}

/** Snap 1 điểm thô → tim đường */
export async function snapPointToStreet(lat: number, lng: number): Promise<[number, number]> {
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
    throw new Error('Tọa độ không hợp lệ');
  }
  const url = `${OSRM_NEAREST}/${lng},${lat}?number=1`;
  const { status, data } = await fetchOsrmJson(url);
  if (status < 200 || status >= 300) throw new Error(`OSRM nearest HTTP ${status}`);
  const waypoints = data.waypoints as Array<{ location?: number[] }> | undefined;
  const wp = data.code === 'Ok' ? waypoints?.[0] : undefined;
  if (!wp?.location || wp.location.length < 2) {
    throw new Error('Không tìm thấy đường gần vị trí này');
  }
  return [wp.location[1], wp.location[0]];
}

export async function snapPointsToStreet<T extends { lat: number; lng: number }>(
  points: T[],
): Promise<Array<T & { snapped: boolean; rawLat?: number; rawLng?: number }>> {
  const out: Array<T & { snapped: boolean; rawLat?: number; rawLng?: number }> = [];
  for (const p of points || []) {
    try {
      const [sLat, sLng] = await snapPointToStreet(p.lat, p.lng);
      out.push({ ...p, lat: sLat, lng: sLng, snapped: true, rawLat: p.lat, rawLng: p.lng });
    } catch {
      out.push({ ...p, snapped: false });
    }
  }
  return out;
}
