const MAPLIBRE_CSS = 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css';
const MAPLIBRE_JS = 'https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.js';
const MAPLIBRE_LEAFLET_JS =
  'https://unpkg.com/@maplibre/maplibre-gl-leaflet@0.0.22/leaflet-maplibre-gl.js';

function loadStylesheet(href: string, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const existing = document.getElementById(id) as HTMLLinkElement | null;
    if (existing) {
      resolve();
      return;
    }
    const link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href = href;
    link.onload = () => resolve();
    link.onerror = () => reject(new Error(`Failed to load CSS: ${href}`));
    document.head.appendChild(link);
  });
}

function loadScript(src: string, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const existing = document.getElementById(id) as HTMLScriptElement | null;
    if (existing) {
      if (existing.dataset.ready === '1') {
        resolve();
        return;
      }
      existing.addEventListener('load', () => resolve(), { once: true });
      existing.addEventListener(
        'error',
        () => reject(new Error(`Failed to load script: ${src}`)),
        { once: true },
      );
      return;
    }
    const script = document.createElement('script');
    script.id = id;
    script.src = src;
    script.async = false;
    script.crossOrigin = 'anonymous';
    script.onload = () => {
      script.dataset.ready = '1';
      resolve();
    };
    script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
    document.body.appendChild(script);
  });
}

function waitFor(check: () => boolean, label: string, timeoutMs = 15000): Promise<void> {
  return new Promise((resolve, reject) => {
    if (check()) {
      resolve();
      return;
    }
    const t0 = Date.now();
    const id = window.setInterval(() => {
      if (check()) {
        window.clearInterval(id);
        resolve();
        return;
      }
      if (Date.now() - t0 > timeoutMs) {
        window.clearInterval(id);
        reject(new Error(label));
      }
    }, 20);
  });
}

let mapLibreChain: Promise<void> | null = null;

/** Leaflet must already be on `window.L`. */
export async function ensureMapLibreLeaflet(): Promise<void> {
  if (!mapLibreChain) {
    mapLibreChain = (async () => {
      await loadStylesheet(MAPLIBRE_CSS, 'maplibre-gl-css-cdn');
      if (typeof window.maplibregl?.Map !== 'function') {
        await loadScript(MAPLIBRE_JS, 'maplibre-gl-js-cdn');
      }
      await waitFor(
        () => typeof window.maplibregl?.Map === 'function',
        'MapLibre GL failed to initialize',
      );
      if (typeof window.L?.maplibreGL !== 'function') {
        await loadScript(MAPLIBRE_LEAFLET_JS, 'maplibre-gl-leaflet-js-cdn');
      }
      await waitFor(
        () => typeof window.L?.maplibreGL === 'function',
        'maplibre-gl-leaflet failed to initialize',
      );
    })().catch((err) => {
      mapLibreChain = null;
      throw err;
    });
  }
  await mapLibreChain;
}
