/** ErpAppLayout `.content` scrolls + pads — GIS map must fill remaining viewport. */

const STYLE_ID = 'rmms-gis-map-page-fill';

const CSS = `
:has(> [data-gis-map-page]) {
  padding: 0 !important;
  overflow: hidden !important;
  display: flex !important;
  flex-direction: column !important;
  min-height: 0 !important;
  height: 100% !important;
  flex: 1 1 auto !important;
}
[data-gis-map-page] {
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
  overflow: hidden;
}
`;

export function ensureGisMapPageFill(): void {
  if (typeof document === 'undefined') return;
  let el = document.getElementById(STYLE_ID);
  if (!el) {
    el = document.createElement('style');
    el.id = STYLE_ID;
    document.head.appendChild(el);
  }
  el.textContent = CSS;
}
