const FORBIDDEN_TILE =
  /openstreetmap\.org|arcgisonline\.com|cartocdn\.com|googleapis\.com|maps\.google/i;

type ApiClientHeaders = {
  defaults?: {
    baseURL?: string;
    headers?: Record<string, unknown> & { common?: Record<string, unknown> };
  };
  getBaseURL?: () => string;
};

function stripSlash(url: string): string {
  return url.trim().replace(/\/$/, '');
}

function toAbsoluteApiBase(raw: string): string {
  const trimmed = stripSlash(raw);
  if (!trimmed) return '';
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  if (trimmed.startsWith('/') && typeof window !== 'undefined') {
    return `${window.location.origin}${trimmed}`;
  }
  return trimmed;
}

/** `{origin}/web-bff/api/v1` — never MapService `:5021`. */
export function resolveGisBffApiBase(): string {
  const client = apiClient as unknown as ApiClientHeaders;
  let raw = '';
  if (typeof client.getBaseURL === 'function') {
    raw = client.getBaseURL() || '';
  }
  if (!raw) raw = client.defaults?.baseURL || '';
  if (!raw) {
    raw = resolveRuntimeApiUrl(import.meta.env.VITE_API_URL as string | undefined);
  }
  return toAbsoluteApiBase(raw);
}

export function gisMvtTileTemplate(layer: string): string {
  return `${resolveGisBffApiBase()}/gis/tiles/${encodeURIComponent(layer)}/{z}/{x}/{y}.pbf`;
}

export function isForbiddenReleaseTileUrl(url: string): boolean {
  return FORBIDDEN_TILE.test(url);
}

function headerString(
  bag: Record<string, unknown> | undefined,
  key: string,
): string {
  if (!bag) return '';
  const direct = bag[key];
  if (typeof direct === 'string' && direct.trim()) return direct.trim();
  const lower = bag[key.toLowerCase()];
  if (typeof lower === 'string' && lower.trim()) return lower.trim();
  return '';
}

/** JWT + company for overlay MVT; guest basemap/mask OK without. */
export function gisTileRequestHeaders(): Record<string, string> {
  const headers: Record<string, string> = {};
  const client = apiClient as unknown as ApiClientHeaders;
  const common = {
    ...(client.defaults?.headers || {}),
    ...(client.defaults?.headers?.common || {}),
  };
  const auth = headerString(common, 'Authorization');
  if (auth) headers.Authorization = auth;
  const company = headerString(common, 'X-Company-Id');
  if (company) headers['X-Company-Id'] = company;
  return headers;
}

