const ROAD_LINE_LAYOUT = {
  'line-cap': 'round',
  'line-join': 'round',
  'line-sort-key': [
    'match',
    ['get', 'class'],
    'motorway',
    50,
    'trunk',
    40,
    'primary',
    30,
    'secondary',
    20,
    'tertiary',
    10,
    0,
  ],
};

/** Fill px @ GL z 5 · 8 · 12 · 14 · 16 · 18 (plateau — cấm interpolate phình sau z16). */
type RoadWStops = [number, number, number, number, number, number];
const ROAD_Z = [5, 8, 12, 14, 16, 18] as const;
const ROAD_FILL_W: Record<string, RoadWStops> = {
  motorway: [0.8, 1.8, 4.4, 7.2, 12, 12],
  trunk: [0.7, 1.6, 4.0, 6.6, 11, 11],
  primary: [0.6, 1.5, 3.6, 6.0, 10, 10],
  secondary: [0.35, 1.05, 2.6, 4.4, 7.2, 7.2],
  tertiary: [0.25, 0.85, 2.1, 3.5, 5.8, 5.8],
};
const ROAD_FILL_MINOR: RoadWStops = [0.2, 0.6, 1.5, 2.8, 4.8, 4.8];
/** Extra width = biên 2 phía (không +0.35px — nhìn thành nét đơn). */
const ROAD_CASE_PAD: RoadWStops = [0.95, 1.4, 2.3, 2.9, 3.6, 3.6];

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function osmRoadWidth(pad: RoadWStops, scale: number): unknown {
  const expr: unknown[] = ['interpolate', ['linear'], ['zoom']];
  for (let i = 0; i < ROAD_Z.length; i++) {
    const extra = pad[i];
    expr.push(ROAD_Z[i], [
      'match',
      ['get', 'class'],
      'motorway',
      round2((ROAD_FILL_W.motorway[i] + extra) * scale),
      'trunk',
      round2((ROAD_FILL_W.trunk[i] + extra) * scale),
      'primary',
      round2((ROAD_FILL_W.primary[i] + extra) * scale),
      'secondary',
      round2((ROAD_FILL_W.secondary[i] + extra) * scale),
      'tertiary',
      round2((ROAD_FILL_W.tertiary[i] + extra) * scale),
      round2((ROAD_FILL_MINOR[i] + extra) * scale),
    ]);
  }
  return expr;
}

function osmRoadFill(kind: ClipStyleKind, theme: ClipTheme): unknown {
  if (kind === 'sat') {
    return [
      'match',
      ['get', 'class'],
      'motorway',
      '#f59e0b',
      'trunk',
      '#fbbf24',
      'primary',
      '#fde68a',
      'secondary',
      '#fef08a',
      theme.roadMinor,
    ];
  }
  return [
    'match',
    ['get', 'class'],
    'motorway',
    OSM_MOTORWAY,
    'trunk',
    OSM_TRUNK,
    'primary',
    OSM_PRIMARY,
    'secondary',
    OSM_SECONDARY,
    theme.roadMinor,
  ];
}

function osmRoadCasing(kind: ClipStyleKind, theme: ClipTheme): unknown {
  if (kind === 'sat') return theme.roadCasing;
  return [
    'match',
    ['get', 'class'],
    'motorway',
    OSM_MOTORWAY_CASE,
    'trunk',
    OSM_TRUNK_CASE,
    'primary',
    OSM_PRIMARY_CASE,
    'secondary',
    OSM_SECONDARY_CASE,
    theme.roadCasing,
  ];
}

function roadPairLayers(
  suffix: string,
  filter: unknown,
  kind: ClipStyleKind,
  theme: ClipTheme,
  scale: number,
): Record<string, unknown>[] {
  const caseOp = kind === 'sat' ? 0.7 : 1;
  return [
    {
      id: `road-casing${suffix}`,
      type: 'line',
      source: 'clip',
      'source-layer': 'transportation',
      filter,
      layout: ROAD_LINE_LAYOUT,
      paint: {
        'line-color': osmRoadCasing(kind, theme),
        'line-opacity': caseOp,
        'line-width': osmRoadWidth(ROAD_CASE_PAD, scale),
      },
    },
    {
      id: `road${suffix}`,
      type: 'line',
      source: 'clip',
      'source-layer': 'transportation',
      filter,
      layout: ROAD_LINE_LAYOUT,
      paint: {
        'line-color': osmRoadFill(kind, theme),
        'line-width': osmRoadWidth([0, 0, 0, 0, 0, 0], scale),
      },
    },
  ];
}

/** Overlay tuyến (Leaflet) — cùng nền/biên OSM Carto primary. Overlay ≠ nét GPS xanh. */
