const VN_CLIP_FIT_PADDING: [number, number] = [8, 8];

export function vnLeafletMapOptions(
  extra?: Record<string, unknown>,
): Record<string, unknown> {
  return {
    zoomControl: true,
    minZoom: VN_CLIP_MIN_ZOOM,
    maxZoom: VN_CLIP_MAX_ZOOM,
    zoom: VN_CLIP_MIN_ZOOM,
    /** Fractional so fill-zoom khớp viewport (zoomSnap 1 → letterbox z5 trên màn lớn). */
    zoomSnap: 0,
    zoomDelta: 1,
    center: [
      (VN_CLIP_MIN_LAT + VN_CLIP_MAX_LAT) / 2,
      (VN_CLIP_MIN_LON + VN_CLIP_MAX_LON) / 2,
    ],
    maxBounds: VN_CLIP_MAX_BOUNDS,
    maxBoundsViscosity: 1,
    worldCopyJump: false,
    ...extra,
  };
}

/** Zoom vừa khít clip VN trong container. Floor SSOT = 5 — không zoom ra thế giới. */
export function vnClipFillZoom(map: L.Map): number {
  const size = map.getSize?.();
  if (!size || size.x < 16 || size.y < 16) return VN_CLIP_MIN_ZOOM;
  if (typeof map.getBoundsZoom !== 'function') return VN_CLIP_MIN_ZOOM;
  const z = map.getBoundsZoom(VN_CLIP_MAX_BOUNDS, false, VN_CLIP_FIT_PADDING);
  if (typeof z !== 'number' || !Number.isFinite(z)) return VN_CLIP_MIN_ZOOM;
  return Math.max(VN_CLIP_MIN_ZOOM, z);
}

export function applyVnClipCamera(map: L.Map): void {
  map.setMinZoom?.(VN_CLIP_MIN_ZOOM);
  const fill = vnClipFillZoom(map);
  map.setMinZoom?.(fill);
  map.setMaxZoom?.(VN_CLIP_MAX_ZOOM);
  map.setMaxBounds?.(VN_CLIP_MAX_BOUNDS);
  const cur = map.getZoom?.();
  if (typeof cur === 'number' && cur < fill - 1e-6) {
    map.setZoom?.(fill);
  } else if (typeof cur === 'number' && cur > VN_CLIP_MAX_ZOOM + 1e-6) {
    map.setZoom?.(VN_CLIP_MAX_ZOOM);
  }
}

/**
 * Default / zoom min = toàn bộ clip VN **fill** viewport.
 * Cấm `maxZoom: 5` (letterbox — GAP-MAP-ZOOM-FILL) · cấm auto fit seed/corridor.
 */
export function fitVnClipMap(map: L.Map): void {
  map.invalidateSize?.({ animate: false });
  applyVnClipCamera(map);
  const fill = vnClipFillZoom(map);
  map.fitBounds(VN_CLIP_MAX_BOUNDS, {
    padding: VN_CLIP_FIT_PADDING,
    maxZoom: fill,
    animate: false,
  });
}

type MapLibreMapApi = {
  resize: () => void;
  getCanvas?: () => HTMLCanvasElement | undefined;
  setStyle?: (style: unknown) => void;
  setRenderWorldCopies?: (value: boolean) => void;
  on?: (event: string, handler: () => void) => void;
};

type MapLibreGlLayer = L.Layer & {
  getMaplibreMap?: () => MapLibreMapApi | undefined;
  _map?: L.Map;
};

function paintLeafletSea(map: L.Map | undefined, kind: ClipStyleKind): void {
  const el = map?.getContainer?.();
  if (el) el.style.background = clipStyleSeaColor(kind);
}

/**
 * Plugin tự set canvas transform + zoom = Leaflet−1.
 * Resize **chỉ** khi container đổi size — cấm zoomend/moveend (scale leftover → pin lệch tim đường).
 */
function resetClipGlCanvas(layer: L.Layer): void {
  (layer as MapLibreGlLayer).getMaplibreMap?.()?.resize?.();
}

function bindClipGlMap(layer: L.Layer, kind: ClipStyleKind): void {
  const gl = (layer as MapLibreGlLayer).getMaplibreMap?.();
  gl?.setRenderWorldCopies?.(false);
  gl?.on?.('style.load', () => {
    gl.setRenderWorldCopies?.(false);
  });
  paintLeafletSea((layer as MapLibreGlLayer)._map, kind);
}

function syncClipGlSize(map: L.Map, layer: L.Layer): void {
  if (!map.getContainer?.()?.isConnected) return;
  resetClipGlCanvas(layer);
  (layer as MapLibreGlLayer).getMaplibreMap?.()?.resize?.();
}

/** Leaflet size + MapLibre canvas — gọi khi dock collapse, zoom, pan (mobile canvas lệch). */
export function syncVnClipGl(map: L.Map, layer?: L.Layer | null): void {
  if (!map.getContainer?.()?.isConnected) return;
  map.invalidateSize?.({ animate: false });
  if (layer && typeof (layer as MapLibreGlLayer).getMaplibreMap === 'function') {
    syncClipGlSize(map, layer);
  }
}

export function applyClipBasemapStyle(layer: L.Layer, kind: ClipStyleKind): void {
  const gl = (layer as MapLibreGlLayer).getMaplibreMap?.();
  gl?.setStyle?.(buildVnClipMapStyle(kind));
  bindClipGlMap(layer, kind);
  const map = (layer as MapLibreGlLayer)._map;
  if (map) window.setTimeout(() => syncClipGlSize(map, layer), 0);
}

/**
 * MapLibre vector layer on Leaflet tilePane. Fail closed — no OSM.org fallback.
 * Fit camera trước addTo — GL init đúng tâm VN (plugin zoom = Leaflet − 1).
 */
export function attachVnClipBasemap(
  map: L.Map,
  kind: ClipStyleKind = 'default',
): L.Layer {
  const Lref = window.L;
  if (typeof Lref.maplibreGL !== 'function') {
    throw new Error('MapLibre clip layer chưa sẵn sàng');
  }
  ensureLinePaneStyles();
  map.attributionControl?.setPrefix?.(false);
  paintLeafletSea(map, kind);
  fitVnClipMap(map);
  const layer = Lref.maplibreGL({
    style: buildVnClipMapStyle(kind),
    pane: 'tilePane',
    attribution: CLIP_MAP_ATTRIBUTION,
    renderWorldCopies: false,
    fadeDuration: 0,
    /** Default 0.1 nới canvas — zoom anim lệch marker (pin kéo khỏi tim đường). */
    padding: 0,
    interactive: false,
    transformRequest: (url: string) => {
      if (isForbiddenReleaseTileUrl(url)) {
        return { url: 'data:application/vnd.mapbox-vector-tile,' };
      }
      if (!url.includes('/gis/tiles/')) {
        return { url };
      }
      const headers = gisTileRequestHeaders();
      return Object.keys(headers).length ? { url, headers } : { url };
    },
  });
  layer.addTo(map);
  bindClipGlMap(layer, kind);
  fitVnClipMap(map);
  const syncGl = () => syncClipGlSize(map, layer);
  const syncFill = () => {
    applyVnClipCamera(map);
    syncGl();
  };
  const onResize = () => syncFill();
  map.invalidateSize?.({ animate: false });
  syncFill();
  map.on('resize', onResize);
  const host = map.getContainer?.();
  let roTimer = 0;
  const ro =
    host && typeof ResizeObserver !== 'undefined'
      ? new ResizeObserver(() => {
          window.clearTimeout(roTimer);
          roTimer = window.setTimeout(syncFill, 50);
        })
      : null;
  if (host && ro) ro.observe(host);
  const onUnload = () => {
    window.clearTimeout(roTimer);
    ro?.disconnect();
    map.off?.('resize', onResize);
  };
  map.on('unload', onUnload);
  window.setTimeout(syncFill, 0);
  window.setTimeout(() => {
    fitVnClipMap(map);
    syncGl();
  }, 50);
  window.setTimeout(syncFill, 200);
  window.setTimeout(syncFill, 600);
  return layer;
}
