import { ensureMapLibreLeaflet } from './loadMapLibreCdn';

const LEAFLET_CSS = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
const LEAFLET_JS = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
const DRAW_CSS = 'https://unpkg.com/leaflet-draw@1.0.4/dist/leaflet.draw.css';
const DRAW_JS = 'https://unpkg.com/leaflet-draw@1.0.4/dist/leaflet.draw.js';

function loadStylesheet(href: string, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const existing = document.getElementById(id) as HTMLLinkElement | null;
    if (existing) {
      resolve();
      return;
    }
    const link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href = href;
    link.onload = () => resolve();
    link.onerror = () => reject(new Error(`Failed to load CSS: ${href}`));
    document.head.appendChild(link);
  });
}

function loadScript(src: string, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const existing = document.getElementById(id) as HTMLScriptElement | null;
    if (existing) {
      if (existing.dataset.ready === '1') {
        resolve();
        return;
      }
      existing.addEventListener('load', () => resolve(), { once: true });
      existing.addEventListener(
        'error',
        () => reject(new Error(`Failed to load script: ${src}`)),
        { once: true },
      );
      return;
    }
    const script = document.createElement('script');
    script.id = id;
    script.src = src;
    script.async = false;
    script.crossOrigin = 'anonymous';
    script.onload = () => {
      script.dataset.ready = '1';
      resolve();
    };
    script.onerror = () => reject(new Error(`Failed to load script: ${src}`));
    document.body.appendChild(script);
  });
}

function waitFor(check: () => boolean, label: string, timeoutMs = 15000): Promise<void> {
  return new Promise((resolve, reject) => {
    if (check()) {
      resolve();
      return;
    }
    const t0 = Date.now();
    const id = window.setInterval(() => {
      if (check()) {
        window.clearInterval(id);
        resolve();
        return;
      }
      if (Date.now() - t0 > timeoutMs) {
        window.clearInterval(id);
        reject(new Error(label));
      }
    }, 20);
  });
}

let leafletChain: Promise<void> | null = null;
let drawChain: Promise<void> | null = null;

export async function ensureLeafletCore(): Promise<void> {
  if (!leafletChain) {
    leafletChain = (async () => {
      await loadStylesheet(LEAFLET_CSS, 'leaflet-css-cdn');
      if (typeof window.L?.map !== 'function') {
        await loadScript(LEAFLET_JS, 'leaflet-js-cdn');
      }
      await waitFor(() => typeof window.L?.map === 'function', 'Leaflet failed to initialize');
      await ensureMapLibreLeaflet();
    })().catch((err) => {
      leafletChain = null;
      throw err;
    });
  }
  await leafletChain;
}

export async function ensureLeafletDraw(): Promise<void> {
  if (!drawChain) {
    drawChain = (async () => {
      await loadStylesheet(DRAW_CSS, 'leaflet-draw-css-cdn');
      await ensureLeafletCore();
      if (window.L?.Control?.Draw) return;
      document.getElementById('leaflet-draw-js-cdn')?.remove();
      await loadScript(DRAW_JS, 'leaflet-draw-js-cdn');
      await waitFor(
        () => Boolean(window.L?.Control?.Draw),
        'Leaflet.Draw failed to initialize',
      );
    })().catch((err) => {
      drawChain = null;
      throw err;
    });
  }
  await drawChain;
}
