import { bindAssetPopup } from './mapAssetIcons';
import {
  VN_CLIP_MAX_LAT,
  VN_CLIP_MAX_LON,
  VN_CLIP_MAX_ZOOM,
  VN_CLIP_MIN_LAT,
  VN_CLIP_MIN_LON,
} from './vnClipBasemap';

/** Map-bar chip — thay Fit (`GAP-WEB-EDIT-01`). */
export const MY_LOCATION_LABEL = 'Vị trí của tôi';
/** Popup **Tên:** — `/map-inspect-popup` · **cấm** dùng trên map-bar. */
export const MY_LOCATION_NAME = 'Vị trí của bạn';
export const MY_LOCATION_TITLE =
  'Định vị GPS — phóng vùng quanh vị trí hiện tại và ghim pin';

const PIN_W = 32;
const PIN_H = 42;
const STYLE_ID = 'rmms-my-loc-css';
const MIN_RADIUS_M = 80;
const MAX_RADIUS_M = 900;

export type MyLocationHold = { group: L.FeatureGroup | null };

function ensureMyLocationStyles(): void {
  if (typeof document === 'undefined') return;
  let el = document.getElementById(STYLE_ID);
  if (!el) {
    el = document.createElement('style');
    el.id = STYLE_ID;
    document.head.appendChild(el);
  }
  el.textContent = `
.leaflet-container img.rmms-my-loc-icon {
  max-width: none !important;
  max-height: none !important;
}
`;
}

function escapeHtml(s: string): string {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Card locate — cùng `{MapPopup}` TS (`GAP-MAP-LOCATE-POPUP-01`). */
export function buildMyLocationPopupHtml(lat: number, lng: number): string {
  const gps =
    Number.isFinite(lat) && Number.isFinite(lng)
      ? `${lat.toFixed(5)}, ${lng.toFixed(5)}`
      : '—';
  return `
<div class="rmms-map-popup">
  <div class="rmms-map-popup__row"><span class="rmms-map-popup__k">Tên:</span> <span class="rmms-map-popup__v rmms-map-popup__v--name">${escapeHtml(MY_LOCATION_NAME)}</span></div>
  <div class="rmms-map-popup__row"><span class="rmms-map-popup__k">GPS:</span> <span class="rmms-map-popup__v">${escapeHtml(gps)}</span></div>
  <div class="rmms-map-popup__meta">GPS · EPSG:4326</div>
</div>`.trim();
}

function pinDataUrl(): string {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 42" width="${PIN_W}" height="${PIN_H}"><path fill="#0f766e" stroke="#fff" stroke-width="2" d="M16 1.8C8.8 1.8 3 7.6 3 14.8 3 24.2 16 40.2 16 40.2S29 24.2 29 14.8C29 7.6 23.2 1.8 16 1.8z"/><circle cx="16" cy="15" r="5.2" fill="#fff"/></svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

function createMyLocationIcon(L: typeof window.L): L.Icon | null {
  if (!L?.icon) return null;
  ensureMyLocationStyles();
  const url = pinDataUrl();
  return L.icon({
    iconUrl: url,
    iconRetinaUrl: url,
    iconSize: [PIN_W, PIN_H],
    iconAnchor: [PIN_W / 2, PIN_H],
    popupAnchor: [0, -PIN_H + 8],
    className: 'rmms-my-loc-icon',
  });
}

function inVnClip(lat: number, lng: number): boolean {
  return (
    lat >= VN_CLIP_MIN_LAT &&
    lat <= VN_CLIP_MAX_LAT &&
    lng >= VN_CLIP_MIN_LON &&
    lng <= VN_CLIP_MAX_LON
  );
}

function regionBounds(lat: number, lng: number, radiusM: number): [[number, number], [number, number]] {
  const dLat = radiusM / 111320;
  const dLng = radiusM / (111320 * Math.max(Math.cos((lat * Math.PI) / 180), 0.2));
  return [
    [lat - dLat, lng - dLng],
    [lat + dLat, lng + dLng],
  ];
}

export function locateErrorMessage(err: unknown): string {
  if (typeof navigator !== 'undefined' && !navigator.geolocation) {
    return 'Trình duyệt không hỗ trợ định vị';
  }
  if (typeof window !== 'undefined' && window.isSecureContext === false) {
    return 'Cần HTTPS để định vị';
  }
  if (err && typeof err === 'object' && 'code' in err) {
    const code = Number((err as GeolocationPositionError).code);
    if (code === 1) return 'Cần cho phép truy cập vị trí';
    if (code === 2) return 'Không lấy được vị trí';
    if (code === 3) return 'Hết thời gian định vị';
  }
  return 'Không lấy được vị trí';
}

/**
 * GPS → pin + vòng vùng (accuracy) → fitBounds.
 * **Cấm** `alert`/`confirm`. List Fit isolate không dùng hàm này.
 */
export function locateUserOnMap(
  map: L.Map,
  L: typeof window.L,
  hold: MyLocationHold,
): Promise<{ lat: number; lng: number }> {
  return new Promise((resolve, reject) => {
    if (!map || !L?.marker || !L?.circle) {
      reject(new Error('Bản đồ chưa sẵn sàng'));
      return;
    }
    if (typeof navigator === 'undefined' || !navigator.geolocation) {
      reject(new Error(locateErrorMessage({ code: 2 })));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const acc = Math.min(
          MAX_RADIUS_M,
          Math.max(MIN_RADIUS_M, Number(pos.coords.accuracy) || MIN_RADIUS_M),
        );
        if (hold.group) {
          try {
            map.removeLayer(hold.group);
          } catch {
            /* gone */
          }
          hold.group = null;
        }
        const group = new L.FeatureGroup();
        const circle = L.circle([lat, lng], {
          radius: acc,
          color: '#0f766e',
          weight: 2,
          fillColor: '#14b8a6',
          fillOpacity: 0.18,
          interactive: false,
        });
        const icon = createMyLocationIcon(L);
        const marker = L.marker([lat, lng], {
          icon: icon || undefined,
          zIndexOffset: 1400,
          title: MY_LOCATION_LABEL,
          keyboard: false,
        });
        bindAssetPopup(marker, buildMyLocationPopupHtml(lat, lng), L);
        group.addLayer(circle);
        group.addLayer(marker);
        group.addTo(map);
        hold.group = group;
        try {
          map.fitBounds(regionBounds(lat, lng, acc), {
            padding: [48, 48],
            maxZoom: VN_CLIP_MAX_ZOOM,
            animate: true,
          });
        } catch {
          map.setView([lat, lng], 16);
        }
        marker.openPopup?.();
        if (!inVnClip(lat, lng)) {
          reject(new Error('Vị trí ngoài phạm vi bản đồ Việt Nam'));
          return;
        }
        resolve({ lat, lng });
      },
      (err) => reject(new Error(locateErrorMessage(err))),
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 10000 },
    );
  });
}
