/**
 * Line levels + isolate focus — port Demo `_shared/map-layout.js`.
 * GAP-MAP-LINE-LEVEL · GAP-MAP-LINE-FOCUS · /agent-dev-oms-map R7b/R7c
 *
 * GAP-MAP-LINE-LEVEL (MFE): Linm reset.css `svg { max-width: 100% }` + Leaflet CSS
 * chỉ exempt `.leaflet-overlay-pane`. Corridor/track custom pane → SVG width 0 →
 * polyline biến mất, pin (img marker) vẫn hiện. Inject CSS cho mọi `.leaflet-pane`.
 */

const LINE_PANE_STYLE_ID = 'rmms-map-line-pane-css';

/** Override Linm reset — custom panes (rmms-corridor / rmms-track) không phải overlay-pane */
const LINE_PANE_CSS = `
.leaflet-container .leaflet-pane svg,
.leaflet-container .leaflet-pane canvas,
.leaflet-container .leaflet-pane > svg,
.leaflet-container .leaflet-overlay-pane svg,
.leaflet-container svg.leaflet-zoom-animated {
  max-width: none !important;
  max-height: none !important;
}
/* Sea = CLIP_THEME.default.sea (OSM muted) — cấm navy !important (lỗ tile 500 = khối xám dọc bờ). */
.leaflet-container {
  background: #8eb8c8;
}
/* Linm reset canvas/svg max-width:100% → MapLibre 0px. Plugin tự set px + transform — cấm width/height 100% trên .leaflet-gl-layer. */
.leaflet-container .leaflet-gl-layer,
.leaflet-container .maplibregl-map,
.leaflet-container .maplibregl-canvas-container {
  max-width: none !important;
  max-height: none !important;
}
.leaflet-container canvas.maplibregl-canvas,
.leaflet-container .leaflet-gl-layer canvas {
  max-width: none !important;
  max-height: none !important;
}
/* GAP-MAP-GL-CLIP-01 — cấm overflow:hidden trên tile-pane (canvas 0px).
 * Cấm overflow:visible trên .leaflet-gl-layer / canvas-container — canvas scale tràn mép, 2 nền. */
.leaflet-container .leaflet-tile-pane {
  overflow: visible;
}
`;

export function ensureLinePaneStyles(): void {
  if (typeof document === 'undefined') return;
  let el = document.getElementById(LINE_PANE_STYLE_ID);
  if (!el) {
    el = document.createElement('style');
    el.id = LINE_PANE_STYLE_ID;
    document.head.appendChild(el);
  }
  el.textContent = LINE_PANE_CSS;
}

/** Cap Fit overview — parity `OVERVIEW_FIT_MAX_ZOOM` / GAP-MAP-FIT-DEFAULT */
const OVERVIEW_FIT_MAX_ZOOM = 13;

export const TRACK_PALETTE = [
  '#2563eb',
  '#dc2626',
  '#7c3aed',
  '#16a34a',
  '#ea580c',
  '#0891b2',
  '#db2777',
  '#ca8a04',
] as const;

export const LINE_PANES = {
  corridor: { name: 'rmms-corridor', zIndex: 350 },
  zone: { name: 'rmms-zone', zIndex: 380 },
  track: { name: 'rmms-track', zIndex: 450 },
  biz: { name: 'rmms-biz', zIndex: 480 },
} as const;

export const CORRIDOR_STYLE = {
  color: '#0f766e',
  weight: 10,
  opacity: 0.28,
  lineCap: 'round' as const,
  lineJoin: 'round' as const,
};

export const TRACK_LINE_DEFAULTS = {
  weight: 6,
  opacity: 0.95,
  lineCap: 'round' as const,
  lineJoin: 'round' as const,
};

/** Zoom khi focus 1 line isolate — chặt hơn overview, chưa street-level */
export const FOCUS_FIT_MAX_ZOOM = 15;

export type LatLngPath = [number, number][];

export type IsolateTrack = {
  id: string;
  code?: string;
  path?: LatLngPath;
};

export function trackColor(id: string): string {
  let hash = 0;
  for (const char of String(id)) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
  return TRACK_PALETTE[hash % TRACK_PALETTE.length];
}

/** Tạo pane z-index: corridor < zone < track < biz < marker(600) */
export function ensureLinePanes(map: L.Map | null | undefined): boolean {
  ensureLinePaneStyles();
  if (!map?.createPane || !map.getPane) return false;
  Object.values(LINE_PANES).forEach((def) => {
    if (!map.getPane!(def.name)) {
      map.createPane!(def.name);
      const pane = map.getPane!(def.name);
      if (pane) {
        pane.style.zIndex = String(def.zIndex);
        pane.style.pointerEvents = 'auto';
      }
    }
  });
  return true;
}

/** Style tuyến master (underlay) — cấm opacity cao đè track */
export function corridorStyle(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    pane: LINE_PANES.corridor.name,
    ...CORRIDOR_STYLE,
    ...overrides,
  };
}

/** Style line nghiệp vụ (track / PCI) — luôn trên corridor */
export function trackLineStyle(
  color?: string,
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    pane: LINE_PANES.track.name,
    color: color || TRACK_PALETTE[0],
    ...TRACK_LINE_DEFAULTS,
    ...overrides,
  };
}

function fitPath(
  map: L.Map,
  path: LatLngPath,
  maxZoom: number,
  padding: [number, number] = [40, 40],
): boolean {
  if (!path?.length) return false;
  let minLat = path[0][0];
  let maxLat = path[0][0];
  let minLng = path[0][1];
  let maxLng = path[0][1];
  path.forEach(([lat, lng]) => {
    minLat = Math.min(minLat, lat);
    maxLat = Math.max(maxLat, lat);
    minLng = Math.min(minLng, lng);
    maxLng = Math.max(maxLng, lng);
  });
  try {
    map.fitBounds(
      [
        [minLat, minLng],
        [maxLat, maxLng],
      ],
      { padding, maxZoom },
    );
    return true;
  } catch {
    return false;
  }
}

/**
 * Click line / legend isolate → auto Fit vào line (hoặc overview khi «Tất cả»).
 * GAP-MAP-LINE-FOCUS
 */
export async function fitIsolateSelection(
  map: L.Map | null | undefined,
  opts: {
    isolatedId?: string | null;
    tracks?: IsolateTrack[];
    overviewPath?: LatLngPath;
    delayMs?: number;
    cache?: { get: (id: string, path: LatLngPath) => Promise<LatLngPath> };
  } = {},
): Promise<boolean> {
  if (!map) return false;
  const delayMs = opts.delayMs ?? 140;
  const tracks = opts.tracks || [];
  const isolatedId = opts.isolatedId;

  const run = async (): Promise<boolean> => {
    map.invalidateSize?.({ animate: false });

    if (isolatedId) {
      const track = tracks.find(
        (t) => t.id === isolatedId || t.code === isolatedId,
      );
      let path = track?.path;
      if (track?.path && opts.cache?.get) {
        try {
          path = await opts.cache.get(track.id || isolatedId, track.path);
        } catch {
          path = track.path;
        }
      }
      if (path?.length) {
        return fitPath(map, path, FOCUS_FIT_MAX_ZOOM, [56, 56]);
      }
    }

    const overview: LatLngPath =
      opts.overviewPath && opts.overviewPath.length > 0
        ? opts.overviewPath
        : tracks.flatMap((t) => (Array.isArray(t.path) ? t.path : []));
    if (!overview.length) return false;
    return fitPath(map, overview, OVERVIEW_FIT_MAX_ZOOM);
  };

  if (delayMs <= 0) return run();
  await new Promise((r) => setTimeout(r, delayMs));
  return run();
}
