import React from 'react';
import { ensureAssetIconStyles } from './mapAssetIcons';
import type { GisInspectModel } from './gisInspectTypes';

type Props = {
  model: GisInspectModel | null;
  loading?: boolean;
  className?: string;
};

function dash(s: string): string {
  const t = String(s ?? '').trim();
  return t || '—';
}

export const GisAssetInspectPanel: React.FC<Props> = ({ model, loading, className }) => {
  React.useEffect(() => {
    ensureAssetIconStyles();
  }, []);

  if (!model) {
    return (
      <div className={className}>
        <p className="rmms-inspect__empty">Chọn tài sản trên bản đồ.</p>
      </div>
    );
  }

  return (
    <div className={className} data-testid="gis-asset-inspect">
      <div className="rmms-map-popup rmms-inspect">
        {model.rows.map((row) => (
          <div key={row.label} className="rmms-map-popup__row">
            <span className="rmms-map-popup__k">{row.label}</span>{' '}
            <span
              className={
                row.name ? 'rmms-map-popup__v rmms-map-popup__v--name' : 'rmms-map-popup__v'
              }
            >
              {dash(row.value)}
            </span>
          </div>
        ))}
        {model.specGroups.map((g) => (
          <div key={g.title} className="rmms-inspect__group">
            <strong className="rmms-inspect__group-title">{g.title}</strong>
            {g.rows.map((r) => (
              <div key={r.key} className="rmms-map-popup__row">
                <span className="rmms-map-popup__k">{r.label}:</span>{' '}
                <span className="rmms-map-popup__v">{dash(r.value)}</span>
              </div>
            ))}
          </div>
        ))}
        <div className="rmms-map-popup__meta">
          {model.snapped === true ? 'snap tim đường' : 'raw'} · EPSG:4326
          {loading ? ' · đang tải hộ chiếu…' : ''}
        </div>
      </div>
    </div>
  );
};
