import React from 'react';
import type { GisSideTabId } from './useGisSideDock';
import styles from './GisMapSideTabs.module.css';

export const GIS_SIDE_TAB_ITEMS: ReadonlyArray<readonly [GisSideTabId, string]> = [
  ['layers', 'Lớp'],
  ['legend', 'Chú giải'],
  ['props', 'Thuộc tính'],
  ['results', 'Kết quả'],
];

type TabItem = readonly [GisSideTabId, string];

type Props = {
  tabs?: ReadonlyArray<TabItem>;
  active: GisSideTabId;
  onSelect: (id: GisSideTabId) => void;
  stacked: boolean;
  bodyOpen: boolean;
  onToggleBody: () => void;
  tabClassName?: string;
  tabOnClassName?: string;
};

function ChevronIcon({ open }: { open: boolean }) {
  return (
    <svg
      className={styles.ico}
      viewBox="0 0 24 24"
      width="18"
      height="18"
      aria-hidden="true"
      focusable="false"
    >
      {open ? (
        <path
          d="M6 9.5 L12 15.5 L18 9.5"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      ) : (
        <path
          d="M6 14.5 L12 8.5 L18 14.5"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
    </svg>
  );
}

/** Tab title row — stacked: height 44px + chevron ẩn/hiện nội dung (full map). */
export const GisMapSideTabs: React.FC<Props> = ({
  tabs = GIS_SIDE_TAB_ITEMS,
  active,
  onSelect,
  stacked,
  bodyOpen,
  onToggleBody,
  tabClassName,
  tabOnClassName,
}) => (
  <div
    className={`${styles.row} ${tabClassName ?? ''}`.trim()}
    data-gis-map-side-tabs
    data-testid="gis-side-tabs"
  >
    <div className={styles.tabs} role="tablist">
      {tabs.map(([id, label]) => (
        <button
          key={id}
          type="button"
          role="tab"
          aria-selected={active === id}
          data-testid={`gis-side-tab-${id}`}
          className={active === id ? tabOnClassName : undefined}
          onClick={() => onSelect(id)}
        >
          {label}
        </button>
      ))}
    </div>
    {stacked ? (
      <button
        type="button"
        className={styles.toggle}
        data-testid="gis-side-body-toggle"
        data-action="gis-side-body-toggle"
        title={bodyOpen ? 'Ẩn nội dung — hiện full bản đồ' : 'Hiện nội dung tab'}
        aria-label={bodyOpen ? 'Ẩn nội dung tab' : 'Hiện nội dung tab'}
        aria-expanded={bodyOpen}
        onClick={onToggleBody}
      >
        <ChevronIcon open={bodyOpen} />
      </button>
    ) : null}
  </div>
);
