export function assetIconHtml(code: string, status: AssetUseStatus = 'ok'): string {
  const meta = assetMeta(code);
  const st = USE_STATUS_META[status] || USE_STATUS_META.ok;
  const broken = status === 'broken';
  const svg = pictogramSvg(code);
  return `<span class="rmms-pin-wrap ${broken ? 'is-broken' : 'is-ok'}" title="${meta.label} · ${st.label}" style="--ring:${st.ring}">${svg}<span class="rmms-pin-badge">${st.badge}</span></span>`;
}

/** Icon only — không badge (dùng checkerboard confirm) */
export function assetIconBareHtml(code: string): string {
  return pictogramSvg(code);
}

export type MapPopupHtmlOpts = {
  /** Tên — catalog 36 (`TYPE_LABEL`) hoặc tên import gov. */
  name?: string;
  /** Mã TS */
  code?: string;
  /** Lý trình KM */
  km?: string;
  /** Tuyến */
  route?: string;
  lat: number;
  lng: number;
  assetCode?: string;
  snapped?: boolean;
  extra?: string;
  /** Extra nhãn:giá trị — camera KPI (`/map-inspect-popup`). */
  extraRows?: Array<{ label: string; value: string }>;
  /** Nút trong popup — `/map-inspect-popup` action (trusted id). */
  action?: { label: string; dataCamDetail: string };
};

function popupDash(s: string | undefined): string {
  const t = String(s ?? '').trim();
  return t || '—';
}

function popupRow(label: string, value: string, opts?: { name?: boolean }): string {
  const nameCls = opts?.name ? ' rmms-map-popup__v--name' : '';
  return `<div class="rmms-map-popup__row"><span class="rmms-map-popup__k">${escapeHtml(label)}</span> <span class="rmms-map-popup__v${nameCls}">${escapeHtml(value)}</span></div>`;
}

function popupGps(lat: number, lng: number): string {
  const a = Number(lat);
  const b = Number(lng);
  return Number.isFinite(a) && Number.isFinite(b) ? `${a.toFixed(5)}, ${b.toFixed(5)}` : '—';
}

/** Popup click tài sản — nhãn Tên / Mã TS / KM / GPS / Tuyến (catalog gov). */
export function buildMapPopupHtml(opts: MapPopupHtmlOpts): string {
  const snap = opts.snapped === true ? 'snap tim đường' : 'raw';
  const extra = String(opts.extra || '').trim();
  const extraRows = (opts.extraRows || [])
    .map((r) => popupRow(r.label, popupDash(r.value)))
    .join('');
  return `
<div class="rmms-map-popup">
  ${popupRow('Tên:', popupDash(opts.name), { name: true })}
  ${popupRow('Mã TS:', popupDash(opts.code))}
  ${popupRow('KM:', popupDash(opts.km))}
  ${popupRow('GPS:', popupGps(opts.lat, opts.lng))}
  ${popupRow('Tuyến:', popupDash(opts.route))}
  ${extraRows}
  ${extra ? `<div class="rmms-map-popup__extra">${escapeHtml(extra)}</div>` : ''}
  ${
    opts.action?.dataCamDetail
      ? `<button type="button" class="rmms-map-popup__btn" data-cam-detail="${escapeHtml(opts.action.dataCamDetail)}">${escapeHtml(opts.action.label || 'Xem chi tiết')}</button>`
      : ''
  }
  <div class="rmms-map-popup__meta">${snap} · EPSG:4326</div>
</div>`.trim();
}

function escapeHtml(s: string): string {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** SVG pictogram QCVN + badge — trùng legend (`assetIconHtml`). Cấm vòng trắng bọc glyph. */
function markerSvg(code: string, status: AssetUseStatus): string {
  const broken = status === 'broken';
  const ring = broken ? '#B91C1C' : '#047857';
  const body = pictogramSvg(code)
    .replace(/^<svg[^>]*>/, '')
    .replace(/<\/svg>$/, '');
  /* Badge = path (không text Unicode) — SVG-as-<img> ổn định hơn */
  const badgeGlyph = broken
    ? `<path d="M23.5 31.2 L28.5 36.2 M28.5 31.2 L23.5 36.2" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/>`
    : `<path d="M22.8 34.2 L25.2 36.6 L29.4 31.8" fill="none" stroke="#fff" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="32" height="40" viewBox="0 0 32 40">
  <ellipse cx="16" cy="37" rx="8" ry="2.4" fill="rgba(15,23,42,0.32)"/>
  <g transform="translate(2,0)">${body}</g>
  <circle cx="26" cy="34" r="7" fill="${ring}" stroke="#ffffff" stroke-width="1.5"/>
  ${badgeGlyph}
</svg>`;
}

function svgDataUrl(svg: string): string {
  /* base64 — tránh edge-case encodeURIComponent + #/Unicode trong một số Chromium */
  if (typeof btoa === 'function') {
    try {
      return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svg)))}`;
    } catch {
      /* fall through */
    }
  }
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}

const leafletIconCache = new Map<string, L.Icon>();
let stylesInjected = false;

function cachedLeafletIcon(
  L: typeof window.L,
  key: string,
  make: () => L.Icon,
): L.Icon {
  const hit = leafletIconCache.get(key);
  if (hit) return hit;
  const icon = make();
  leafletIconCache.set(key, icon);
  return icon;
}

