/** Marker image size (data-URI) — neo đáy-giữa */
export const ASSET_ICON_SIZE: [number, number] = [32, 40];
export const ASSET_ICON_ANCHOR: [number, number] = [16, 40];
export const ASSET_POPUP_ANCHOR: [number, number] = [0, -40];

/** Pin / cụm tài sản — chỉ xem. Cấm Leaflet drag / Draw edit. */
export const ASSET_DISPLAY_MARKER_OPTS = {
  draggable: false,
} as const;

const CLUSTER_FILL = '#0f766e';

/** Overview (z≤8): bubble size theo COUNT(*) cell — neo tâm (centroid). */
export function clusterIconSize(count: number): number {
  if (count >= 50_000) return 52;
  if (count >= 10_000) return 46;
  if (count >= 1_000) return 40;
  return 34;
}

/** Compact label trên bubble — cấm `7.410` (vi-VN) vì dọc chữ trên icon hẹp. */
export function formatClusterCount(n: number): string {
  if (!Number.isFinite(n) || n < 0) return '0';
  if (n >= 1_000_000) {
    const v = n / 1_000_000;
    return `${v >= 10 ? Math.round(v) : v.toFixed(1).replace(/\.0$/, '')}tr`;
  }
  if (n >= 1000) {
    const v = n / 1000;
    return `${n >= 10_000 ? Math.round(v) : v.toFixed(1).replace(/\.0$/, '')}k`;
  }
  return String(Math.round(n));
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function clusterBubbleSvg(label: string, size: number): string {
  const r = size / 2;
  const font = size >= 46 ? 14 : size >= 40 ? 12 : 11;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
  <circle cx="${r}" cy="${r}" r="${r - 2.2}" fill="${CLUSTER_FILL}" stroke="#ffffff" stroke-width="2.2"/>
  <text x="${r}" y="${r}" dy="0.38em" text-anchor="middle" fill="#ffffff"
    font-size="${font}" font-weight="700" font-family="system-ui,Segoe UI,sans-serif">${escapeXml(label)}</text>
</svg>`;
}

function typeClusterSvg(assetCode: string, count: number): string {
  const body = pictogramSvg(assetCode)
    .replace(/^<svg[^>]*>/, '')
    .replace(/<\/svg>$/, '');
  const label = formatClusterCount(count);
  const color = assetMeta(assetCode).color;
  const chipW = Math.max(22, 10 + label.length * 6.5);
  const chipX = 40 - chipW;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="40" height="52" viewBox="0 0 40 52">
  <ellipse cx="16" cy="49" rx="8" ry="2.2" fill="rgba(15,23,42,0.32)"/>
  <g transform="translate(2,4)">${body}</g>
  <rect x="${chipX}" y="0" width="${chipW}" height="16" rx="8" fill="${color}" stroke="#ffffff" stroke-width="1.5"/>
  <text x="${chipX + chipW / 2}" y="12" text-anchor="middle" fill="#ffffff"
    font-size="10" font-weight="700" font-family="system-ui,Segoe UI,sans-serif">${escapeXml(label)}</text>
</svg>`;
}

/** Loại lớn — pin QCVN + đếm vùng (không DivIcon). */
export function createTypeClusterLeafletIcon(
  L: typeof window.L,
  count: number,
  assetCode: string,
): L.Icon | null {
  if (!L?.icon) return null;
  ensureAssetIconStyles();
  const key = `type:${assetCode || 'TS'}:${formatClusterCount(count)}`;
  return cachedLeafletIcon(L, key, () => {
    const url = svgDataUrl(typeClusterSvg(assetCode || 'TS', count));
    return L.icon({
      iconUrl: url,
      iconRetinaUrl: url,
      iconSize: [40, 52],
      iconAnchor: [16, 50],
      popupAnchor: [0, -40],
      className: 'rmms-type-cluster-icon',
    });
  });
}

/** LOD0 cluster — L.icon data-URI tròn (fallback khi chưa có assetCode). */
export function createClusterLeafletIcon(
  L: typeof window.L,
  count: number,
  assetCode?: string,
): L.Icon | null {
  if (assetCode) return createTypeClusterLeafletIcon(L, count, assetCode);
  if (!L?.icon) return null;
  ensureAssetIconStyles();
  const size = clusterIconSize(count);
  const key = `bubble:${size}:${formatClusterCount(count)}`;
  return cachedLeafletIcon(L, key, () => {
    const url = svgDataUrl(clusterBubbleSvg(formatClusterCount(count), size));
    return L.icon({
      iconUrl: url,
      iconRetinaUrl: url,
      iconSize: [size, size],
      iconAnchor: [size / 2, size / 2],
      popupAnchor: [0, -size / 2],
      className: 'rmms-cluster-icon',
    });
  });
}

export function ensureAssetIconStyles(): void {
  if (typeof document === 'undefined') return;
  const el = document.getElementById('rmms-asset-icon-css');
  if (el) {
    el.textContent = POPUP_AND_PIN_CSS;
    stylesInjected = true;
    return;
  }
  if (stylesInjected) return;
  const style = document.createElement('style');
  style.id = 'rmms-asset-icon-css';
  style.textContent = POPUP_AND_PIN_CSS;
  document.head.appendChild(style);
  stylesInjected = true;
}

export function createAssetLeafletIcon(
  L: typeof window.L,
  code: string,
  status: AssetUseStatus = 'ok',
  opts: { iconUrl?: string; iconSize?: [number, number] } = {},
): L.DivIcon | L.Icon | null {
  if (!L) return null;
  ensureAssetIconStyles();
  if (opts.iconUrl) {
    const size = opts.iconSize || ASSET_ICON_SIZE;
    return L.icon({
      iconUrl: opts.iconUrl,
      iconRetinaUrl: opts.iconUrl,
      iconSize: size,
      iconAnchor: [size[0] / 2, size[1]],
      popupAnchor: [0, -size[1]],
      className: 'rmms-asset-icon',
    });
  }
  const cacheKey = `pin:${String(code || 'TS').toUpperCase()}:${status}`;
  return cachedLeafletIcon(L, cacheKey, () => {
    const url = svgDataUrl(markerSvg(code, status));
    return L.icon({
      iconUrl: url,
      iconRetinaUrl: url,
      iconSize: ASSET_ICON_SIZE,
      iconAnchor: ASSET_ICON_ANCHOR,
      popupAnchor: ASSET_POPUP_ANCHOR,
      className: 'rmms-asset-icon',
    });
  });
}

export function bindAssetPopup(
  layer: { bindPopup?: (c: string | L.Popup, o?: Record<string, unknown>) => unknown },
  html: string,
  L?: typeof window.L,
): void {
  if (typeof layer.bindPopup !== 'function') return;
  ensureAssetIconStyles();
  const opts = {
    maxWidth: 340,
    minWidth: 240,
    className: 'rmms-map-popup-wrap',
    autoPan: true,
    closeButton: true,
  };
  if (L?.popup) {
    layer.bindPopup(L.popup(opts).setContent(html));
    return;
  }
  layer.bindPopup(html, opts);
}

export function buildAssetLegendHtml(entries: Array<{ assetCode?: string; code?: string; status?: AssetUseStatus }>): string {
  ensureAssetIconStyles();
  const seen = new Set<string>();
  const parts: string[] = [];
  for (const e of entries || []) {
    const code = e.assetCode || e.code || 'TS';
    const status: AssetUseStatus = e.status === 'broken' ? 'broken' : 'ok';
    const key = `${code}:${status}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const meta = assetMeta(code);
    const st = USE_STATUS_META[status];
    parts.push(
      `<span class="legend-icon">${assetIconHtml(code, status)}<span>${meta.label} · ${st.label}</span></span>`,
    );
  }
  return parts.join('');
}
