import { useCallback, useEffect, useState } from 'react';
import { useDeviceContentSize } from '@linm-soft-org/linm-web-common-components';
import { ensureGisMapPageFill } from './gisMapPageFill';

/** Matches existing GIS `.app` stack — `max-width: 960px` (không invent breakpoint). */
export const GIS_MAP_STACK_MQ = '(max-width: 960px)';

export type GisAssetSideTabId = 'layers' | 'legend' | 'props' | 'results';
export type GisPatrolSideTabId = 'tuan-duong' | 'tuan-kiem' | 'chi-tiet';
export type GisSideTabId = GisAssetSideTabId | GisPatrolSideTabId;

export function useGisMapStacked(): boolean {
  const [stacked, setStacked] = useState(
    () => typeof window !== 'undefined' && window.matchMedia(GIS_MAP_STACK_MQ).matches,
  );

  useEffect(() => {
    const mq = window.matchMedia(GIS_MAP_STACK_MQ);
    const sync = () => setStacked(mq.matches);
    const timer = window.setTimeout(() => {
      sync();
      mq.addEventListener('change', sync);
    }, 0);
    return () => {
      window.clearTimeout(timer);
      mq.removeEventListener('change', sync);
    };
  }, []);

  return stacked;
}

/**
 * Side dock tabs — desktop: body always on.
 * Stacked (≤960): tab title 44px · body show/hide.
 * Mobile small: default hide body (full map).
 */
export function useGisSideDock(initial: GisSideTabId = 'layers') {
  const { isSmall } = useDeviceContentSize();
  const stacked = useGisMapStacked();
  const [sideTab, setSideTabState] = useState<GisSideTabId>(initial);
  const [sideBodyOpen, setSideBodyOpen] = useState(() => !isSmall);

  useEffect(() => {
    const timer = window.setTimeout(() => ensureGisMapPageFill(), 0);
    return () => window.clearTimeout(timer);
  }, []);

  const setSideTab = useCallback((tab: GisSideTabId) => {
    setSideTabState(tab);
    setSideBodyOpen(true);
  }, []);

  const onTabClick = useCallback(
    (tab: GisSideTabId) => {
      if (stacked && tab === sideTab && sideBodyOpen) {
        setSideBodyOpen(false);
        return;
      }
      setSideTabState(tab);
      if (stacked) setSideBodyOpen(true);
    },
    [stacked, sideTab, sideBodyOpen],
  );

  const toggleBody = useCallback(() => {
    setSideBodyOpen((open) => !open);
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      if (!stacked) setSideBodyOpen(true);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [stacked]);

  return {
    sideTab,
    setSideTab,
    onTabClick,
    sideBodyOpen,
    setSideBodyOpen,
    toggleBody,
    stacked,
    isSmall,
  };
}
