import React from 'react';

/** GIS list SSOT — icon phóng full / thu dock (không chữ Dock/Full). */
export const MapViewToggleIcon: React.FC<{ expanded: boolean; className?: string }> = ({
  expanded,
  className,
}) =>
  expanded ? (
    <svg
      className={className}
      viewBox="0 0 24 24"
      width="18"
      height="18"
      aria-hidden="true"
      focusable="false"
    >
      <rect x="2.5" y="2.5" width="19" height="19" fill="none" stroke="currentColor" strokeWidth="1.7" rx="0.5" />
      <rect
        x="11.5"
        y="4"
        width="8.5"
        height="8.5"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeDasharray="2.2 1.8"
      />
      <path d="M18.2 5.8 L12.5 11.5" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" />
      <path
        d="M12.5 7.8 V11.5 H16.2"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  ) : (
    <svg
      className={className}
      viewBox="0 0 24 24"
      width="18"
      height="18"
      aria-hidden="true"
      focusable="false"
    >
      <rect
        x="2.5"
        y="2.5"
        width="19"
        height="19"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeDasharray="2.2 1.8"
        rx="0.5"
      />
      <rect x="4" y="11.5" width="8.5" height="8.5" fill="none" stroke="currentColor" strokeWidth="1.7" />
      <path d="M13.2 10.8 L18.5 5.5" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" />
      <path
        d="M14.2 5.5 H18.5 V9.8"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.7"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
