/**
 * SSOT pin check-in — mọi điểm trên `{PatrolGis}` (`/gis/tuan-duong`).
 * `/map-checkin-pin`
 */
import { bindAssetPopup } from './mapAssetIcons';

export type CheckInStopKind = 'done' | 'pending' | 'skipped';

export const CHECKIN_PIN = {
  done: { fill: '#3CB448', label: 'Đã check-in' },
  pending: { fill: '#94a3b8', label: 'Chưa check-in' },
  skipped: { fill: '#64748b', label: 'Bỏ qua' },
} as const;

export type CheckInPopupHtmlOpts = {
  personName: string;
  jobTitle?: string;
  placeName: string;
  route?: string;
  lat: number;
  lng: number;
  snapped?: boolean;
  checkedAt?: string | null;
  kind?: CheckInStopKind;
};

export type CheckInMarkerOpts = CheckInPopupHtmlOpts & {
  n: number;
  kind: CheckInStopKind;
  latlng: [number, number];
};

export function checkInKindOf(stop: {
  kind?: CheckInStopKind;
  pending?: boolean;
  checkedAt?: string | null;
}): CheckInStopKind {
  if (stop.kind === 'done' || stop.kind === 'pending' || stop.kind === 'skipped') {
    return stop.kind;
  }
  if (stop.pending) return 'pending';
  if (stop.checkedAt) return 'done';
  return 'pending';
}

export function checkInPinFill(kind: CheckInStopKind): string {
  return CHECKIN_PIN[kind].fill;
}

export function checkInStatusLabel(kind: CheckInStopKind): string {
  return CHECKIN_PIN[kind].label;
}

/** Teardrop số — không chip giờ (trạng thái + màu trong popup). */
export function checkInPinSvg(n: number, fill: string): string {
  const label = String(n);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="28" height="36" viewBox="0 0 28 36">
  <ellipse cx="14" cy="34.2" rx="6" ry="1.6" fill="rgba(15,23,42,.35)"/>
  <path d="M14 1.6 C7.2 1.6 2.2 7.2 2.2 14.2 C2.2 22.8 14 34 14 34 C14 34 25.8 22.8 25.8 14.2 C25.8 7.2 20.8 1.6 14 1.6 Z"
    fill="${fill}" stroke="#fff" stroke-width="2.2"/>
  <text x="14" y="17.2" text-anchor="middle" fill="#fff" font-size="11" font-weight="700"
    font-family="system-ui,sans-serif">${label}</text>
</svg>`;
}

export function checkInPinIcon(
  L: typeof window.L,
  n: number,
  kind: CheckInStopKind,
): L.Icon {
  ensureCheckInPinStyles();
  const svg = checkInPinSvg(n, checkInPinFill(kind));
  const url = `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
  return L.icon({
    iconUrl: url,
    iconRetinaUrl: url,
    iconSize: [28, 36],
    iconAnchor: [14, 34],
    popupAnchor: [0, -28],
    className: 'rmms-ci-pin-icon',
  });
}

export function buildCheckInPopupHtml(opts: CheckInPopupHtmlOpts): string {
  const kind = checkInKindOf(opts);
  const snap = opts.snapped === true ? 'snap tuyến chính' : 'raw';
  const { fill, label } = CHECKIN_PIN[kind];
  const when = opts.checkedAt
    ? new Date(opts.checkedAt).toLocaleString('vi-VN', { hour12: false })
    : '';
  const time =
    kind === 'done' && when
      ? ` <span class="rmms-map-popup__when">${escapeHtml(when)}</span>`
      : '';
  const statusRow = `<div class="rmms-map-popup__row"><span class="rmms-map-popup__k">Trạng thái:</span> <span class="rmms-map-popup__v"><span class="rmms-map-popup__status" style="background:${fill}">${label}</span>${time}</span></div>`;
  return `
<div class="rmms-map-popup">
  ${popupRow('Họ tên:', popupDash(opts.personName), { name: true })}
  ${popupRow('Chức vụ:', popupDash(opts.jobTitle))}
  ${popupRow('Tên vị trí:', popupDash(opts.placeName))}
  ${popupRow('Tuyến đường:', popupDash(opts.route))}
  ${popupRow('Tọa độ:', popupGps(opts.lat, opts.lng))}
  ${statusRow}
  <div class="rmms-map-popup__meta">${snap} · EPSG:4326</div>
</div>`.trim();
}

/** Mọi pin check-in trên trang tuần — cùng icon + popup SSOT. */
export function addCheckInMarker(
  L: typeof window.L,
  layer: { addLayer: (m: L.Layer) => unknown },
  opts: CheckInMarkerOpts,
): L.Marker {
  const marker = L.marker(opts.latlng, {
    icon: checkInPinIcon(L, opts.n, opts.kind),
    zIndexOffset: 800,
    riseOnHover: true,
  });
  layer.addLayer(marker);
  bindAssetPopup(marker, buildCheckInPopupHtml(opts), L);
  return marker;
}

export function ensureCheckInPinStyles(): void {
  if (typeof document === 'undefined') return;
  const id = 'rmms-checkin-pin-ssot-v1';
  let el = document.getElementById(id);
  if (!el) {
    el = document.createElement('style');
    el.id = id;
    document.head.appendChild(el);
  }
  el.textContent = `
.leaflet-container img.leaflet-marker-icon.rmms-ci-pin-icon,
.leaflet-marker-pane img.rmms-ci-pin-icon {
  background: transparent !important;
  border: 0 !important;
  width: 28px !important;
  height: 36px !important;
  max-width: none !important;
  max-height: none !important;
  display: block !important;
}
`;
}

function popupDash(s: string | undefined): string {
  const t = String(s ?? '').trim();
  return t || '—';
}

function popupRow(label: string, value: string, opts?: { name?: boolean }): string {
  const nameCls = opts?.name ? ' rmms-map-popup__v--name' : '';
  return `<div class="rmms-map-popup__row"><span class="rmms-map-popup__k">${escapeHtml(label)}</span> <span class="rmms-map-popup__v${nameCls}">${escapeHtml(value)}</span></div>`;
}

function popupGps(lat: number, lng: number): string {
  const a = Number(lat);
  const b = Number(lng);
  return Number.isFinite(a) && Number.isFinite(b) ? `${a.toFixed(5)}, ${b.toFixed(5)}` : '—';
}

function escapeHtml(s: string): string {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
